      if (exp.sinkCalls > 0 && exp.event) {
        for (const ev of newEvents) {
          if (ev.orderId !== exp.event.orderId)
            result.failures.push(`${callLabel}: event orderId ${ev.orderId} ≠ ${exp.event.orderId}`);
          if (ev.actorId !== exp.event.actorId)
            result.failures.push(`${callLabel}: event actorId ${ev.actorId} ≠ ${exp.event.actorId}`);
          if (ev.amountCents !== exp.event.amountCents)
            result.failures.push(`${callLabel}: event amountCents ${ev.amountCents} ≠ ${exp.event.amountCents}`);
          if (ev.currency !== exp.event.currency)
            result.failures.push(`${callLabel}: event currency ${ev.currency} ≠ ${exp.event.currency}`);
        }
      }

      // Order state transition
      if (exp.orderAfterRefunded !== undefined && orderAfter) {
        if (orderAfter.refunded !== exp.orderAfterRefunded) {
          result.failures.push(
            `${callLabel}: expected order.refunded=${exp.orderAfterRefunded}; observed ${orderAfter.refunded}`
          );
        }
      }

