    result.status = 'ERROR';
    result.error = err instanceof Error ? `${err.message}\n${err.stack}` : String(err);
    return result;
  }

  result.status = result.failures.length > 0 ? 'FAIL' : 'PASS';
  return result;
}

/**
 * Run all five cases through both entry paths (ten results).
 * @returns {SuiteReport}
 */
