    console.log(`  expectation met: ${mutationExpect.expectationMet}`);
    console.log(`  witnesses: ${mutationExpect.witnesses.join(', ')}`);

    writeFileSync(join(EVIDENCE_DIR, 'mutation-stdout.txt'), mutation.stdout + '\n' + mutation.stderr);

    phases.push({
