/* ============================================================
   Rite — styles.css
   Warm paper audit sheet. No animations except the 120ms hover.
   ============================================================ */

:root {
  --ink: #171A18;
  --paper: #F2EFE7;
  --paper-2: #E8E4D9;
  --vermilion: #D94B35;       /* non-text or ≥24px/18.66px-bold only */
  --vermilion-text: #A8321F;  /* small text on paper, ≈5.8:1 */
  --sage: #68736B;             /* ≥18.66px bold only, ≈4.3:1 on paper */
  --sage-text: #58625B;        /* small secondary text, ≈5.5:1 */
  --rule: rgba(23, 26, 24, .16);
  --sans: "Source Sans 3", "Source Sans Pro", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;

  /* Type scale (16px root) */
  --text-meta:    0.8125rem;  /* 13px */
  --text-table:   0.9375rem;  /* 15px */
  --text-body:    1rem;       /* 16px */
  --text-section: 1.25rem;    /* 20px */
  --text-rule:    1.75rem;    /* 28px */
  --text-verdict: 2.5rem;     /* 40px */

  /* Spacing */
  --sp-1: 4px;
  --sp-2: 8px;
  --sp-3: 12px;
  --sp-4: 16px;
  --sp-6: 24px;
  --sp-8: 32px;
  --sp-12: 48px;
}

/* Large screens: bump root so body text is ≥17px at 1920×1080 */
@media (min-width: 1800px) {
  :root { font-size: 17px; }
}

/* ---- Reset / base ---- */
*, *::before, *::after { box-sizing: border-box; }

html, body {
  margin: 0; padding: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--sans);
  font-size: var(--text-body);
  line-height: 1.6;
}

#root {
  min-height: 100vh;
}

/* Focus ring — keyboard-only */
:focus-visible {
  outline: 2px solid var(--ink);
  outline-offset: 2px;
}
:focus:not(:focus-visible) { outline: none; }

/* ---- Utility ---- */
.mono  { font-family: var(--mono); }
.meta  { font-size: var(--text-meta); color: var(--sage-text); font-family: var(--mono); }
.muted { color: var(--sage-text); }
.sr-only {
  position: absolute; width: 1px; height: 1px;
  padding: 0; margin: -1px; overflow: hidden;
  clip: rect(0,0,0,0); white-space: nowrap; border: 0;
}

/* ---- Header ---- */
.header {
  height: 64px;
  border-bottom: 1px solid var(--rule);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 var(--sp-8);
  gap: var(--sp-6);
  background: var(--paper);
}

.header-left {
  display: flex;
  align-items: center;
  gap: var(--sp-6);
  flex-shrink: 0;
}

.header-wordmark {
  width: 160px;
  height: auto;
  min-width: 140px;
  display: block;
}

.header-tagline {
  font-size: var(--text-body);
  color: var(--sage-text);
  white-space: nowrap;
}

.header-right {
  font-size: var(--text-table);
  color: var(--sage-text);
  text-align: right;
  white-space: nowrap;
}

/* Mobile: stack tagline below wordmark */
@media (max-width: 899px) {
  .header {
    height: auto;
    min-height: 64px;
    flex-wrap: wrap;
    padding: var(--sp-3) var(--sp-4);
  }
  .header-tagline { white-space: normal; }
  .header-right { font-size: var(--text-meta); width: 100%; text-align: left; }
}

/* ---- Rule band ---- */
.rule-band {
  padding: var(--sp-6) var(--sp-8) var(--sp-6);
  border-bottom: 1px solid var(--rule);
  background: var(--paper);
}

.rule-band .eyebrow {
  font-size: var(--text-meta);
  font-family: var(--mono);
  color: var(--sage-text);
  letter-spacing: .06em;
  margin: 0 0 var(--sp-3);
}

.rule-band h1 {
  font-family: var(--sans);
  font-size: var(--text-rule);
  font-weight: 600;
  line-height: 1.25;
  margin: 0 0 var(--sp-2);
  color: var(--ink);
}

.rule-band .rule-sub {
  font-size: var(--text-body);
  color: var(--sage-text);
  margin: 0 0 var(--sp-2);
}

.rule-band .scope {
  font-size: var(--text-table);
  color: var(--sage-text);
}

@media (max-width: 899px) {
  .rule-band { padding: var(--sp-4); }
  .rule-band h1 { font-size: calc(var(--text-rule) * .85); }
}

/* ---- Workbench grid ---- */
.workbench {
  display: grid;
  grid-template-columns: minmax(280px, .8fr) minmax(460px, 1.5fr) minmax(340px, 1fr);
  gap: var(--sp-6);
  padding: var(--sp-6) var(--sp-8);
  align-items: start;
}

@media (min-width: 900px) and (max-width: 1279px) {
  .workbench {
    grid-template-columns: 1fr 1fr;
  }
  .case-detail-col {
    grid-column: 1 / -1;
  }
}

@media (max-width: 899px) {
  .workbench {
    grid-template-columns: 1fr;
    padding: var(--sp-4);
    gap: var(--sp-4);
  }
}

/* ---- Section headings ---- */
.section-label {
  font-size: var(--text-section);
  font-weight: 600;
  margin: 0 0 var(--sp-4);
  color: var(--ink);
}

/* ---- Buttons ---- */
.btn {
  display: inline-flex;
  align-items: center;
  gap: var(--sp-2);
  font-family: var(--sans);
  font-size: var(--text-body);
  font-weight: 600;
  cursor: pointer;
  border-radius: 2px;
  padding: var(--sp-2) var(--sp-4);
  transition: background 120ms linear;
  border: 1px solid var(--ink);
  background: var(--ink);
  color: var(--paper);
}
.btn:disabled,
.btn[aria-busy="true"] {
  opacity: .5;
  cursor: not-allowed;
}
@media (prefers-reduced-motion: no-preference) {
  .btn { transition: background 120ms linear, border-color 120ms linear; }
}

.btn-secondary {
  background: transparent;
  color: var(--ink);
}

.btn-small {
  font-size: var(--text-table);
  font-weight: 400;
  padding: 2px var(--sp-3);
}

/* ---- Verdict ---- */
.verdict {
  margin: var(--sp-4) 0;
  min-height: 2.5em;
}

.verdict-text {
  font-size: var(--text-verdict);
  font-weight: 700;
  line-height: 1.1;
  color: var(--ink);
}

.verdict-text.fail {
  color: var(--vermilion); /* large text, ≥40px — passes */
}

.verdict-sub {
  font-size: var(--text-body);
  color: var(--sage-text);
  margin-top: var(--sp-2);
}

.verdict-idle {
  font-size: var(--text-body);
  color: var(--sage-text);
  font-style: italic;
}

/* ---- PathMap ---- */
.path-map {
  border: 1px solid var(--rule);
  border-radius: 2px;
  padding: var(--sp-4);
  background: var(--paper);
}

.path-map-filters {
  display: flex;
  gap: var(--sp-2);
  margin-bottom: var(--sp-4);
  flex-wrap: wrap;
}

.path-filter-btn {
  font-family: var(--sans);
  font-size: var(--text-table);
  background: transparent;
  border: 1px solid var(--rule);
  border-radius: 2px;
  padding: 2px var(--sp-3);
  cursor: pointer;
  color: var(--ink);
}
.path-filter-btn[aria-pressed="true"] {
  background: var(--ink);
  color: var(--paper);
  border-color: var(--ink);
}
@media (prefers-reduced-motion: no-preference) {
  .path-filter-btn { transition: background 120ms linear; }
}

.path-lanes {
  display: flex;
  flex-direction: column;
  gap: 0;
  position: relative;
}

.path-lane {
  border: 1px solid var(--rule);
  border-radius: 2px 2px 0 0;
  padding: var(--sp-3) var(--sp-4);
  margin-bottom: 0;
  background: var(--paper);
  position: relative;
}

.path-lane + .path-lane {
  border-top: none;
  border-radius: 0;
}

.path-lane.selected {
  background: var(--paper-2);
  border-left: 3px solid var(--vermilion);
}

.path-lane-name {
  font-weight: 600;
  font-size: var(--text-body);
}

.path-lane-file {
  font-family: var(--mono);
  font-size: var(--text-meta);
  color: var(--sage-text);
}

.path-lane-status {
  font-size: var(--text-meta);
  color: var(--sage-text);
  margin-top: var(--sp-1);
}

.path-connector {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--sp-1) 0;
  color: var(--sage-text);
  font-size: var(--text-meta);
  font-family: var(--mono);
}

/* Converging lines visual: two lanes → one sink */
.sink-node {
  border: 1px solid var(--rule);
  border-radius: 0 0 2px 2px;
  padding: var(--sp-3) var(--sp-4);
  background: var(--paper-2);
  border-top: 2px solid var(--vermilion);
  position: relative;
}

.sink-label {
  font-weight: 600;
  font-size: var(--text-body);
}

.sink-guard {
  font-size: var(--text-meta);
  color: var(--sage-text);
  font-family: var(--mono);
  margin-top: var(--sp-1);
}

/* ---- Results table ---- */
.results-col {
  display: flex;
  flex-direction: column;
}

.run-controls {
  display: flex;
  gap: var(--sp-3);
  margin-bottom: var(--sp-4);
  flex-wrap: wrap;
  align-items: center;
}

.table-scroll {
  overflow-x: auto;
}

.results-table {
  width: 100%;
  min-width: 560px;
  border-collapse: collapse;
  font-size: var(--text-table);
}

.results-table caption {
  text-align: left;
  font-size: var(--text-section);
  font-weight: 600;
  margin-bottom: var(--sp-3);
  caption-side: top;
  color: var(--ink);
}

.results-table th {
  text-align: left;
  font-size: var(--text-meta);
  font-weight: 600;
  padding: var(--sp-2) var(--sp-3);
  border-bottom: 1px solid var(--rule);
  color: var(--sage-text);
  white-space: nowrap;
}

.results-table td {
  padding: var(--sp-2) var(--sp-3);
  border-bottom: 1px solid var(--rule);
  vertical-align: middle;
}

.results-table tr.selected td {
  background: var(--paper-2);
}

.results-table tr.selected td:first-child {
  box-shadow: inset 3px 0 0 var(--vermilion);
  padding-left: calc(var(--sp-3) - 3px);
}

@media (prefers-reduced-motion: no-preference) {
  .results-table td { transition: background 120ms linear; }
}

/* Status badges — text only, never colour-only signal */
.status-pass {
  font-weight: 600;
  color: var(--ink);
  outline: 1px solid var(--ink);
  padding: 1px var(--sp-2);
  border-radius: 2px;
  white-space: nowrap;
}

.status-fail {
  font-weight: 700;
  color: var(--vermilion-text);
  outline: 2px solid var(--vermilion);
  padding: 1px var(--sp-2);
  border-radius: 2px;
  white-space: nowrap;
}

.status-error {
  font-weight: 600;
  background: var(--ink);
  color: var(--paper);
  padding: 1px var(--sp-2);
  border-radius: 2px;
  white-space: nowrap;
}

.status-notrun {
  color: var(--sage-text);
  font-size: var(--text-meta);
  white-space: nowrap;
}

/* Case selector button in table */
.case-btn {
  background: transparent;
  border: none;
  font-family: var(--sans);
  font-size: var(--text-table);
  cursor: pointer;
  padding: 0;
  text-align: left;
  color: var(--ink);
  text-decoration: underline;
  text-underline-offset: 2px;
}
.case-btn[aria-pressed="true"] {
  font-weight: 600;
  text-decoration-thickness: 2px;
}

/* ---- CaseDetail ---- */
.case-detail {
  border: 1px solid var(--rule);
  border-radius: 2px;
  padding: var(--sp-4);
  background: var(--paper);
  min-height: 120px;
}

.case-detail-header {
  margin: 0 0 var(--sp-4);
}

.case-detail-title {
  font-size: var(--text-section);
  font-weight: 600;
  margin: 0 0 var(--sp-2);
}

.detail-empty {
  color: var(--sage-text);
  font-style: italic;
}

.call-block {
  margin: var(--sp-4) 0;
  border-top: 1px solid var(--rule);
  padding-top: var(--sp-3);
}

.call-block-title {
  font-weight: 600;
  font-size: var(--text-table);
  margin: 0 0 var(--sp-3);
}

.call-columns {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--sp-4);
}

.call-col-label {
  font-size: var(--text-meta);
  font-family: var(--mono);
  color: var(--sage-text);
  margin: 0 0 var(--sp-2);
}

.call-field {
  font-size: var(--text-table);
  margin: 0 0 var(--sp-2);
}

.call-field strong {
  color: var(--sage-text);
  font-weight: 600;
}

.pre-block {
  font-family: var(--mono);
  font-size: var(--text-meta);
  background: var(--paper-2);
  padding: var(--sp-3);
  border: 1px solid var(--rule);
  border-radius: 2px;
  overflow-x: auto;
  white-space: pre-wrap;
  word-break: break-all;
  max-height: 200px;
  margin: var(--sp-2) 0;
}

.failures-list {
  background: var(--paper-2);
  border-left: 3px solid var(--vermilion);
  padding: var(--sp-3) var(--sp-4);
  margin: var(--sp-3) 0;
  border-radius: 0 2px 2px 0;
}

.failures-list li {
  font-family: var(--mono);
  font-size: var(--text-meta);
  color: var(--vermilion-text);
  margin: var(--sp-1) 0;
}

.events-block {
  margin-top: var(--sp-3);
}

.events-label {
  font-size: var(--text-meta);
  color: var(--sage-text);
  font-family: var(--mono);
  margin: 0 0 var(--sp-2);
}

.event-item {
  font-family: var(--mono);
  font-size: var(--text-meta);
  background: var(--paper-2);
  border: 1px solid var(--rule);
  border-radius: 2px;
  padding: var(--sp-2) var(--sp-3);
  margin-bottom: var(--sp-2);
}

/* ---- Recorded proof ---- */
.recorded-proof {
  margin: 0 var(--sp-8) var(--sp-8);
  border: 1px solid var(--rule);
  border-radius: 2px;
}

@media (max-width: 899px) {
  .recorded-proof { margin: 0 var(--sp-4) var(--sp-6); }
}

.recorded-proof summary {
  padding: var(--sp-3) var(--sp-4);
  cursor: pointer;
  font-weight: 600;
  font-size: var(--text-body);
  list-style: none;
  user-select: none;
  border-radius: 2px;
}
.recorded-proof summary::-webkit-details-marker { display: none; }
.recorded-proof summary::before {
  content: '▶ ';
  font-size: var(--text-meta);
  color: var(--sage-text);
}
.recorded-proof[open] summary::before { content: '▼ '; }

.recorded-proof-body {
  padding: var(--sp-4);
  border-top: 1px solid var(--rule);
}

.proof-summary-line {
  font-size: var(--text-table);
  color: var(--sage-text);
  margin: 0 0 var(--sp-4);
}

.phase-block {
  margin-bottom: var(--sp-6);
  border: 1px solid var(--rule);
  border-radius: 2px;
  padding: var(--sp-3) var(--sp-4);
}

.phase-header {
  display: flex;
  align-items: baseline;
  gap: var(--sp-3);
  margin-bottom: var(--sp-2);
  flex-wrap: wrap;
}

.phase-label {
  font-weight: 600;
  font-size: var(--text-body);
}

.phase-meta {
  font-family: var(--mono);
  font-size: var(--text-meta);
  color: var(--sage-text);
}

.proof-how-list {
  margin: var(--sp-4) 0 0;
  padding-left: var(--sp-6);
}

.proof-how-list li {
  font-size: var(--text-table);
  color: var(--sage-text);
  margin-bottom: var(--sp-1);
}

/* ---- Footer ---- */
.footer {
  border-top: 1px solid var(--rule);
  padding: var(--sp-4) var(--sp-8);
  text-align: center;
  font-size: var(--text-meta);
  color: var(--sage-text);
  margin-top: var(--sp-8);
}

