  padding: 0 var(--sp-8);
  gap: var(--sp-6);
  background: var(--paper);
}

.header-left {
  display: flex;
  align-items: center;
  gap: var(--sp-6);
  flex-shrink: 0;
}

.header-wordmark {
  width: 160px;
  height: auto;
  min-width: 140px;
  display: block;
}

.header-tagline {
  font-size: var(--text-body);
  color: var(--sage-text);
  white-space: nowrap;
}

.header-right {
  font-size: var(--text-table);
  color: var(--sage-text);
