.rule-band {
  padding: var(--sp-6) var(--sp-8) var(--sp-6);
  border-bottom: 1px solid var(--rule);
  background: var(--paper);
}

.rule-band .eyebrow {
  font-size: var(--text-meta);
  font-family: var(--mono);
  color: var(--sage-text);
  letter-spacing: .06em;
  margin: 0 0 var(--sp-3);
}

.rule-band h1 {
  font-family: var(--sans);
  font-size: var(--text-rule);
  font-weight: 600;
  line-height: 1.25;
  margin: 0 0 var(--sp-2);
  color: var(--ink);
}

.rule-band .rule-sub {
  font-size: var(--text-body);
  color: var(--sage-text);
  margin: 0 0 var(--sp-2);
}

.rule-band .scope {
  font-size: var(--text-table);
  color: var(--sage-text);
}

@media (max-width: 899px) {
