  align-items: center;
  gap: var(--sp-2);
  font-family: var(--sans);
  font-size: var(--text-body);
  font-weight: 600;
  cursor: pointer;
  border-radius: 2px;
  padding: var(--sp-2) var(--sp-4);
  transition: background 120ms linear;
  border: 1px solid var(--ink);
  background: var(--ink);
  color: var(--paper);
