.verdict-text {
  font-size: var(--text-verdict);
  font-weight: 700;
  line-height: 1.1;
  color: var(--ink);
}

.verdict-text.fail {
  color: var(--vermilion); /* large text, ≥40px — passes */
}

.verdict-sub {
  font-size: var(--text-body);
  color: var(--sage-text);
  margin-top: var(--sp-2);
}

.verdict-idle {
  font-size: var(--text-body);
  color: var(--sage-text);
  font-style: italic;
}

