.path-map {
  border: 1px solid var(--rule);
  border-radius: 2px;
  padding: var(--sp-4);
  background: var(--paper);
}

.path-map-filters {
  display: flex;
  gap: var(--sp-2);
  margin-bottom: var(--sp-4);
  flex-wrap: wrap;
}

.path-filter-btn {
  font-family: var(--sans);
  font-size: var(--text-table);
  background: transparent;
  border: 1px solid var(--rule);
  border-radius: 2px;
  padding: 2px var(--sp-3);
  cursor: pointer;
  color: var(--ink);
}
.path-filter-btn[aria-pressed="true"] {
  background: var(--ink);
  color: var(--paper);
  border-color: var(--ink);
}
@media (prefers-reduced-motion: no-preference) {
  .path-filter-btn { transition: background 120ms linear; }
}

.path-lanes {
  display: flex;
  flex-direction: column;
  gap: 0;
  position: relative;
}

.path-lane {
  border: 1px solid var(--rule);
  border-radius: 2px 2px 0 0;
  padding: var(--sp-3) var(--sp-4);
  margin-bottom: 0;
  background: var(--paper);
  position: relative;
}

.path-lane + .path-lane {
  border-top: none;
  border-radius: 0;
}

.path-lane.selected {
  background: var(--paper-2);
  border-left: 3px solid var(--vermilion);
}

.path-lane-name {
  font-weight: 600;
  font-size: var(--text-body);
}

.path-lane-file {
  font-family: var(--mono);
  font-size: var(--text-meta);
  color: var(--sage-text);
}

.path-lane-status {
  font-size: var(--text-meta);
  color: var(--sage-text);
  margin-top: var(--sp-1);
}

.path-connector {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--sp-1) 0;
  color: var(--sage-text);
  font-size: var(--text-meta);
  font-family: var(--mono);
}

/* Converging lines visual: two lanes → one sink */
.sink-node {
  border: 1px solid var(--rule);
  border-radius: 0 0 2px 2px;
  padding: var(--sp-3) var(--sp-4);
  background: var(--paper-2);
  border-top: 2px solid var(--vermilion);
  position: relative;
}

.sink-label {
  font-weight: 600;
  font-size: var(--text-body);
}

.sink-guard {
  font-size: var(--text-meta);
  color: var(--sage-text);
  font-family: var(--mono);
  margin-top: var(--sp-1);
}

/* ---- Results table ---- */
.results-col {
  display: flex;
  flex-direction: column;
}

.run-controls {
  display: flex;
  gap: var(--sp-3);
  margin-bottom: var(--sp-4);
  flex-wrap: wrap;
  align-items: center;
}

.table-scroll {
  overflow-x: auto;
}

.results-table {
  width: 100%;
  min-width: 560px;
  border-collapse: collapse;
  font-size: var(--text-table);
}

.results-table caption {
  text-align: left;
  font-size: var(--text-section);
  font-weight: 600;
  margin-bottom: var(--sp-3);
  caption-side: top;
  color: var(--ink);
}

.results-table th {
  text-align: left;
  font-size: var(--text-meta);
  font-weight: 600;
  padding: var(--sp-2) var(--sp-3);
  border-bottom: 1px solid var(--rule);
  color: var(--sage-text);
  white-space: nowrap;
}

.results-table td {
  padding: var(--sp-2) var(--sp-3);
  border-bottom: 1px solid var(--rule);
  vertical-align: middle;
}

.results-table tr.selected td {
  background: var(--paper-2);
}

.results-table tr.selected td:first-child {
  box-shadow: inset 3px 0 0 var(--vermilion);
  padding-left: calc(var(--sp-3) - 3px);
}

@media (prefers-reduced-motion: no-preference) {
  .results-table td { transition: background 120ms linear; }
}

/* Status badges — text only, never colour-only signal */
.status-pass {
  font-weight: 600;
  color: var(--ink);
  outline: 1px solid var(--ink);
  padding: 1px var(--sp-2);
  border-radius: 2px;
  white-space: nowrap;
}

.status-fail {
  font-weight: 700;
  color: var(--vermilion-text);
  outline: 2px solid var(--vermilion);
  padding: 1px var(--sp-2);
  border-radius: 2px;
  white-space: nowrap;
}

.status-error {
  font-weight: 600;
  background: var(--ink);
  color: var(--paper);
  padding: 1px var(--sp-2);
  border-radius: 2px;
  white-space: nowrap;
}

.status-notrun {
  color: var(--sage-text);
  font-size: var(--text-meta);
  white-space: nowrap;
}

/* Case selector button in table */
.case-btn {
  background: transparent;
  border: none;
  font-family: var(--sans);
  font-size: var(--text-table);
  cursor: pointer;
  padding: 0;
  text-align: left;
  color: var(--ink);
  text-decoration: underline;
  text-underline-offset: 2px;
}
.case-btn[aria-pressed="true"] {
  font-weight: 600;
  text-decoration-thickness: 2px;
}

/* ---- CaseDetail ---- */
.case-detail {
  border: 1px solid var(--rule);
  border-radius: 2px;
  padding: var(--sp-4);
  background: var(--paper);
  min-height: 120px;
}

.case-detail-header {
  margin: 0 0 var(--sp-4);
}

.case-detail-title {
  font-size: var(--text-section);
  font-weight: 600;
  margin: 0 0 var(--sp-2);
}

.detail-empty {
  color: var(--sage-text);
  font-style: italic;
}

.call-block {
  margin: var(--sp-4) 0;
  border-top: 1px solid var(--rule);
  padding-top: var(--sp-3);
}

.call-block-title {
  font-weight: 600;
  font-size: var(--text-table);
  margin: 0 0 var(--sp-3);
}

.call-columns {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--sp-4);
}

.call-col-label {
  font-size: var(--text-meta);
  font-family: var(--mono);
  color: var(--sage-text);
  margin: 0 0 var(--sp-2);
}

.call-field {
  font-size: var(--text-table);
  margin: 0 0 var(--sp-2);
}

.call-field strong {
  color: var(--sage-text);
  font-weight: 600;
}

.pre-block {
  font-family: var(--mono);
  font-size: var(--text-meta);
  background: var(--paper-2);
  padding: var(--sp-3);
  border: 1px solid var(--rule);
  border-radius: 2px;
  overflow-x: auto;
  white-space: pre-wrap;
  word-break: break-all;
  max-height: 200px;
  margin: var(--sp-2) 0;
}

.failures-list {
  background: var(--paper-2);
  border-left: 3px solid var(--vermilion);
  padding: var(--sp-3) var(--sp-4);
  margin: var(--sp-3) 0;
  border-radius: 0 2px 2px 0;
}

.failures-list li {
  font-family: var(--mono);
  font-size: var(--text-meta);
  color: var(--vermilion-text);
  margin: var(--sp-1) 0;
}

.events-block {
  margin-top: var(--sp-3);
}

.events-label {
  font-size: var(--text-meta);
  color: var(--sage-text);
  font-family: var(--mono);
  margin: 0 0 var(--sp-2);
}

.event-item {
  font-family: var(--mono);
  font-size: var(--text-meta);
  background: var(--paper-2);
  border: 1px solid var(--rule);
  border-radius: 2px;
  padding: var(--sp-2) var(--sp-3);
  margin-bottom: var(--sp-2);
}

/* ---- Recorded proof ---- */
.recorded-proof {
  margin: 0 var(--sp-8) var(--sp-8);
  border: 1px solid var(--rule);
  border-radius: 2px;
}

@media (max-width: 899px) {
  .recorded-proof { margin: 0 var(--sp-4) var(--sp-6); }
}

.recorded-proof summary {
  padding: var(--sp-3) var(--sp-4);
  cursor: pointer;
  font-weight: 600;
  font-size: var(--text-body);
  list-style: none;
  user-select: none;
  border-radius: 2px;
}
.recorded-proof summary::-webkit-details-marker { display: none; }
.recorded-proof summary::before {
  content: '▶ ';
  font-size: var(--text-meta);
  color: var(--sage-text);
}
.recorded-proof[open] summary::before { content: '▼ '; }

.recorded-proof-body {
  padding: var(--sp-4);
  border-top: 1px solid var(--rule);
}

.proof-summary-line {
  font-size: var(--text-table);
  color: var(--sage-text);
  margin: 0 0 var(--sp-4);
}

.phase-block {
  margin-bottom: var(--sp-6);
  border: 1px solid var(--rule);
  border-radius: 2px;
  padding: var(--sp-3) var(--sp-4);
}

.phase-header {
  display: flex;
  align-items: baseline;
  gap: var(--sp-3);
  margin-bottom: var(--sp-2);
  flex-wrap: wrap;
}

.phase-label {
  font-weight: 600;
  font-size: var(--text-body);
}

.phase-meta {
  font-family: var(--mono);
  font-size: var(--text-meta);
  color: var(--sage-text);
}

.proof-how-list {
  margin: var(--sp-4) 0 0;
  padding-left: var(--sp-6);
}

.proof-how-list li {
  font-size: var(--text-table);
  color: var(--sage-text);
  margin-bottom: var(--sp-1);
}

/* ---- Footer ---- */
.footer {
  border-top: 1px solid var(--rule);
  padding: var(--sp-4) var(--sp-8);
  text-align: center;
  font-size: var(--text-meta);
  color: var(--sage-text);
  margin-top: var(--sp-8);
}

