+  font-size: var(--text-table);
+  margin: 0 0 var(--sp-3);
+}
+
+.call-columns {
+  display: grid;
+  grid-template-columns: 1fr 1fr;
+  gap: var(--sp-4);
+}
+
+.call-col-label {
+  font-size: var(--text-meta);
+  font-family: var(--mono);
+  color: var(--sage-text);
+  margin: 0 0 var(--sp-2);
+}
+
+.call-field {
+  font-size: var(--text-table);
+  margin: 0 0 var(--sp-2);
