+
+.pre-block {
+  font-family: var(--mono);
+  font-size: var(--text-meta);
+  background: var(--paper-2);
+  padding: var(--sp-3);
+  border: 1px solid var(--rule);
+  border-radius: 2px;
+  overflow-x: auto;
+  white-space: pre-wrap;
+  word-break: break-all;
+  max-height: 200px;
+  margin: var(--sp-2) 0;
+}
+
+.failures-list {
