import React, { useState, useEffect, useRef } from 'react';
import { runSuite, runCase } from './checks.js';
import { CASES } from './cases.js';

// ============================================================
// PathMap
// ============================================================

function getLaneStatus(entry, lastRun) {
  if (!lastRun) return 'Not run';
  const results = lastRun.data?.results ?? [];
  const forEntry = results.filter(r => r.entry === entry);
  if (forEntry.length === 0) return 'Not run';
  const passed = forEntry.filter(r => r.status === 'PASS').length;
  return `${passed} of ${forEntry.length} current checks passed`;
}

function PathMap({ pathFilter, setPathFilter, lastRun }) {
  const bothPressed = pathFilter === 'all';
  const customerPressed = pathFilter === 'customer';
  const supportPressed = pathFilter === 'support';

  const customerStatus = getLaneStatus('customer', lastRun);
  const supportStatus = getLaneStatus('support', lastRun);

  return (
    <div className="path-map">
      <div className="path-map-filters">
        <button
          className="path-filter-btn"
          aria-pressed={bothPressed}
          onClick={() => setPathFilter('all')}
        >
          Both paths
        </button>
        <button
          className="path-filter-btn"
          aria-pressed={customerPressed}
          onClick={() => setPathFilter('customer')}
        >
          Customer
        </button>
        <button
          className="path-filter-btn"
          aria-pressed={supportPressed}
          onClick={() => setPathFilter('support')}
        >
          Support
        </button>
      </div>

      <div className="path-lanes">
        {(pathFilter === 'all' || pathFilter === 'customer') && (
          <div className={`path-lane${pathFilter === 'customer' ? ' selected' : ''}`}>
            <div className="path-lane-name">Customer path</div>
            <div className="path-lane-file mono">src/refunds.js · customerRefund()</div>
            <div className="path-lane-status">{customerStatus}</div>
          </div>
        )}
        {(pathFilter === 'all' || pathFilter === 'support') && (
          <div className={`path-lane${pathFilter === 'support' ? ' selected' : ''}`}>
            <div className="path-lane-name">Support path</div>
            <div className="path-lane-file mono">src/refunds.js · supportRefund()</div>
            <div className="path-lane-status">{supportStatus}</div>
          </div>
        )}

        <div className="path-connector" aria-hidden="true">↓ both route through ↓</div>

        <div className="sink-node">
          <div className="sink-label">Shared enforcement + sink</div>
          <div className="sink-guard mono">
            src/refunds.js · authorizeAndRefund() → issueRefund()
          </div>
          <div className="sink-guard" style={{ marginTop: 4 }}>
            Guard location: owner · paid · not refunded
          </div>
        </div>
      </div>
    </div>
  );
}

// ============================================================
// ResultsTable
// ============================================================

function statusEl(status) {
  if (status === 'PASS') return <span className="status-pass">PASS</span>;
  if (status === 'FAIL') return <span className="status-fail">FAIL</span>;
  if (status === 'ERROR') return <span className="status-error">ERROR</span>;
  return <span className="status-notrun">Not run</span>;
}

function ResultsTable({ lastRun, pathFilter, selectedKey, setSelectedKey, onRunCase, running }) {
  // Build rows from cross-product of CASES × entries
  const entries = ['customer', 'support'];
  const rows = [];
  for (const caseSpec of CASES) {
    for (const entry of entries) {
      if (pathFilter !== 'all' && pathFilter !== entry) continue;
      const id = `${caseSpec.id}:${entry}`;
      const result = lastRun?.data?.results?.find(r => r.id === id) ?? null;
      rows.push({ id, caseSpec, entry, result });
    }
  }

  return (
    <div>
      <div
        role="region"
        aria-label="Current checks results"
        tabIndex={0}
        className="table-scroll"
      >
        <table className="results-table">
          <caption>Current checks</caption>
          <thead>
            <tr>
              <th>Case</th>
              <th>Entry</th>
              <th>Status</th>
              <th>Run</th>
            </tr>
          </thead>
          <tbody>
            {rows.map(({ id, caseSpec, entry, result }) => (
              <tr key={id} className={selectedKey === id ? 'selected' : ''}>
                <td>
                  <button
                    className="case-btn"
                    aria-pressed={selectedKey === id}
                    aria-controls="case-detail"
                    onClick={() => setSelectedKey(id)}
                  >
                    {caseSpec.label}
                  </button>
                </td>
                <td>{entry}</td>
                <td>{result ? statusEl(result.status) : statusEl(null)}</td>
                <td>
                  <button
                    className="btn btn-small btn-secondary"
                    disabled={running}
                    aria-busy={running ? 'true' : undefined}
                    aria-label={`Run ${caseSpec.label} on ${entry} path`}
                    onClick={() => onRunCase(caseSpec, entry)}
                  >
                    Run
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

// ============================================================
// CaseDetail
// ============================================================

function formatCurrency(amountCents, currency) {
  try {
    return new Intl.NumberFormat(undefined, { style: 'currency', currency }).format(
      amountCents / 100
    );
  } catch {
    return `${amountCents} ${currency}`;
  }
}

function EventItem({ ev }) {
  return (
    <div className="event-item">
      <div><span className="muted">refundId:</span> {ev.refundId}</div>
      <div><span className="muted">orderId:</span> {ev.orderId}</div>
      <div><span className="muted">actorId:</span> {ev.actorId}</div>
      <div>
        <span className="muted">amount:</span>{' '}
        {ev.amountCents} cents ({formatCurrency(ev.amountCents, ev.currency)})
      </div>
      <div><span className="muted">currency:</span> {ev.currency}</div>
    </div>
  );
}

function CallBlock({ callObs, index }) {
  const { expected, observed } = callObs;
  return (
    <div className="call-block">
      <div className="call-block-title">Call {index + 1}</div>
      <div className="call-columns">
        <div>
          <div className="call-col-label">Expected</div>
          <div className="call-field"><strong>ok:</strong> {String(expected.ok)}</div>
          <div className="call-field"><strong>code:</strong> {expected.code}</div>
          <div className="call-field"><strong>sinkCalls:</strong> {expected.sinkCalls}</div>
        </div>
        <div>
          <div className="call-col-label">Observed</div>
          <div className="call-field"><strong>ok:</strong> {String(observed.result?.ok)}</div>
          <div className="call-field"><strong>code:</strong> {observed.result?.code}</div>
          <div className="call-field"><strong>sinkCalls:</strong> {observed.sinkCalls}</div>
          {observed.orderAfter && (
            <>
              <div className="call-col-label" style={{ marginTop: 8 }}>orderAfter</div>
              <pre className="pre-block">{JSON.stringify(observed.orderAfter, null, 2)}</pre>
            </>
          )}
        </div>
      </div>
      <div className="events-block">
        <div className="events-label">
          New sink events ({observed.events?.length ?? 0})
        </div>
        {observed.events?.length > 0
          ? observed.events.map((ev, i) => <EventItem key={i} ev={ev} />)
          : <div className="muted" style={{ fontSize: 'var(--text-meta)' }}>No refund events.</div>
        }
      </div>
    </div>
  );
}

function CaseDetail({ selectedKey, lastRun }) {
  const result = lastRun?.data?.results?.find(r => r.id === selectedKey) ?? null;

  return (
    <section id="case-detail" className="case-detail" aria-labelledby="case-detail-heading">
      <h2 id="case-detail-heading" className="sr-only">Case detail</h2>
      {!result ? (
        <div className="detail-empty">Select a case to see expected and observed effects.</div>
      ) : (
        <>
          <div className="case-detail-header">
            <div className="case-detail-title">{result.label}</div>
            <div style={{ display: 'flex', gap: 'var(--sp-3)', alignItems: 'center' }}>
              <span className="muted" style={{ fontSize: 'var(--text-table)' }}>
                {result.entry} path
              </span>
              {result.status === 'PASS' && <span className="status-pass">PASS</span>}
              {result.status === 'FAIL' && <span className="status-fail">FAIL</span>}
              {result.status === 'ERROR' && <span className="status-error">ERROR</span>}
            </div>
          </div>

          {result.failures?.length > 0 && (
            <div className="failures-list">
              <ul>
                {result.failures.map((f, i) => <li key={i}>{f}</li>)}
              </ul>
            </div>
          )}

          {result.error && (
            <div className="failures-list">
              <ul><li>{result.error}</li></ul>
            </div>
          )}

          {result.calls?.map((callObs, i) => (
            <CallBlock key={i} callObs={callObs} index={i} />
          ))}
        </>
      )}
    </section>
  );
}

// ============================================================
// RecordedProof
// ============================================================

function PhaseBlock({ phase }) {
  const metColor = phase.expectationMet ? 'var(--ink)' : 'var(--vermilion-text)';
  return (
    <div className="phase-block">
      <div className="phase-header">
        <span className="phase-label">{phase.label}</span>
        <span className={`status-${phase.resultStatus?.toLowerCase?.() ?? 'notrun'}`}>
          {phase.resultStatus}
        </span>
        <span style={{ color: metColor, fontWeight: 600, fontSize: 'var(--text-table)' }}>
          {phase.expectationMet ? '✓ expected observation met' : '✗ expected observation not met'}
        </span>
      </div>
      <div className="phase-meta">
        command: {phase.command}
        {' · '}exit: {phase.exitCode ?? 'null'}
        {phase.signal ? ` · signal: ${phase.signal}` : ''}
        {phase.processError ? ` · error: ${phase.processError}` : ''}
      </div>
      {phase.witnesses?.length > 0 && (
        <div className="phase-meta" style={{ marginTop: 4 }}>
          witnesses: {phase.witnesses.join(', ')}
        </div>
      )}
      <div className="phase-meta" style={{ marginTop: 4 }}>
        sourceHash: {phase.sourceHash ?? 'n/a'}
      </div>
    </div>
  );
}

function RecordedProof() {
  const [proofState, setProofState] = useState('idle'); // idle|loading|missing|invalid|error|ready
  const [proof, setProof]   = useState(null);
  const [proofMsg, setProofMsg] = useState('');
  const detailsRef = useRef(null);

  function validateProof(data) {
    if (!data || typeof data !== 'object') return false;
    if (data.schemaVersion !== 1) return false;
    if (typeof data.generatedAt !== 'string') return false;
    if (data.status !== 'PASS' && data.status !== 'FAIL') return false;
    if (!Array.isArray(data.phases) || data.phases.length !== 4) return false;
    const phaseIds = ['baseline', 'fixed', 'mutation', 'restored'];
    for (const id of phaseIds) {
      if (!data.phases.find(p => p.id === id)) return false;
    }
    for (const phase of data.phases) {
      if (typeof phase.label !== 'string') return false;
      if (typeof phase.command !== 'string') return false;
      if (phase.exitCode !== null && typeof phase.exitCode !== 'number') return false;
      if (typeof phase.expectationMet !== 'boolean') return false;
    }
    return true;
  }

  async function loadProof() {
    setProofState('loading');
    try {
      const url = `${import.meta.env.BASE_URL}evidence/proof.json`;
      const resp = await fetch(url);
      if (resp.status === 404) {
        setProofState('missing');
        return;
      }
      if (!resp.ok) {
        setProofState('error');
        setProofMsg(`HTTP ${resp.status}`);
        return;
      }
      let data;
      try { data = await resp.json(); } catch {
        setProofState('invalid');
        return;
      }
      if (!validateProof(data)) {
        setProofState('invalid');
        return;
      }
      setProof(data);
      setProofState('ready');
    } catch (e) {
      setProofState('error');
      setProofMsg(String(e?.message ?? e));
    }
  }

  function handleToggle(e) {
    if (e.target.open && proofState === 'idle') {
      loadProof();
    }
  }

  return (
    <details className="recorded-proof" ref={detailsRef} onToggle={handleToggle}>
      <summary>Recorded proof</summary>
      <div className="recorded-proof-body">
        <p className="proof-summary-line">
          Recorded proof: CLI runs captured while building this sample. Not re-run here.
        </p>

        {proofState === 'idle' && (
          <div className="muted">Open to load recorded proof file.</div>
        )}
        {proofState === 'loading' && (
          <div className="muted">Loading…</div>
        )}
        {proofState === 'missing' && (
          <div className="muted">
            No recorded proof file in this build. Current checks still run live.
          </div>
        )}
        {proofState === 'invalid' && (
          <div className="muted">
            Recorded proof file did not match the expected shape, so it is not shown.
          </div>
        )}
        {proofState === 'error' && (
          <div className="muted">
            Could not load recorded proof: {proofMsg}. Current checks still run live.
          </div>
        )}

        {proofState === 'ready' && proof && (
          <>
            <div style={{ marginBottom: 'var(--sp-4)', display: 'flex', gap: 'var(--sp-4)', flexWrap: 'wrap', alignItems: 'baseline' }}>
              <strong>Overall: </strong>
              {proof.status === 'PASS'
                ? <span className="status-pass">PASS</span>
                : <span className="status-fail">FAIL</span>
              }
              <span className="meta">Generated: {proof.generatedAt}</span>
              <span className="meta">Node: {proof.runtime?.node}</span>
            </div>
            <div style={{ marginBottom: 'var(--sp-4)' }}>
              <div className="meta">policy hash: {proof.hashes?.policy}</div>
              <div className="meta">cases hash: {proof.hashes?.cases}</div>
              <div className="meta">checks hash: {proof.hashes?.checks}</div>
              <div className="meta">test hash: {proof.hashes?.test}</div>
            </div>
            {proof.phases.map(phase => (
              <PhaseBlock key={phase.id} phase={phase} />
            ))}
          </>
        )}

        <h3 style={{ fontSize: 'var(--text-table)', fontWeight: 600, marginTop: 'var(--sp-6)' }}>
          How this was made
        </h3>
        <ol className="proof-how-list">
          <li>In Bob IDE: trace both entry paths</li>
          <li>Write black-box behavior checks</li>
          <li>Fix at the shared enforcement point</li>
          <li>Remove the ownership check and watch checks fail</li>
          <li>Restore it and watch them pass</li>
        </ol>
      </div>
    </details>
  );
}

// ============================================================
// App
// ============================================================

export default function App() {
  const [status, setStatus]       = useState('idle');      // 'idle'|'running'|'complete'|'error'
  const [lastRun, setLastRun]     = useState(null);         // {kind:'suite'|'case', data}
  const [runError, setRunError]   = useState(null);
  const [selectedKey, setSelectedKey] = useState(null);
  const [pathFilter, setPathFilter]   = useState('all');

  const running = status === 'running';

  // Derive report data
  const report = lastRun?.data ?? null;
  // If runner returned ERROR status, surface it
  const effectiveStatus = (() => {
    if (status === 'error') return 'error';
    if (status !== 'complete') return status;
    if (!report || !Array.isArray(report.results) || report.results.length === 0) return 'error';
    return report.status?.toLowerCase() ?? 'error';
  })();

  // Auto-select first failing/error result after a run
  useEffect(() => {
    if (status !== 'complete' || !report?.results?.length) return;
    const failOrError = report.results.find(r => r.status === 'FAIL' || r.status === 'ERROR');
    if (failOrError) {
      setSelectedKey(failOrError.id);
    } else if (!selectedKey || !report.results.find(r => r.id === selectedKey)) {
      setSelectedKey(report.results[0]?.id ?? null);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [status, report]);

  async function handleRunAll() {
    setStatus('running');
    setRunError(null);
    try {
      const data = runSuite();
      setLastRun({ kind: 'suite', data });
      setStatus('complete');
    } catch (e) {
      setRunError(String(e?.message ?? e));
      setLastRun(null);
      setStatus('error');
    }
  }

  async function handleRunCase(caseSpec, entry) {
    setStatus('running');
    setRunError(null);
    try {
      const result = runCase(caseSpec, entry);
      setLastRun({ kind: 'case', data: { status: result.status, results: [result] } });
      setSelectedKey(result.id);
      setStatus('complete');
    } catch (e) {
      setRunError(String(e?.message ?? e));
      setLastRun(null);
      setStatus('error');
    }
  }

  function handleReset() {
    setStatus('idle');
    setLastRun(null);
    setRunError(null);
    setSelectedKey(null);
  }

  // Verdict
  const verdictEl = (() => {
    if (status === 'idle') {
      return (
        <div className="verdict-idle">
          Not run yet. Checks run in this browser against the fixed sample.
        </div>
      );
    }
    if (status === 'running') {
      return <div className="verdict-idle">Running…</div>;
    }
    if (status === 'error') {
      return (
        <div>
          <div className="verdict-text">ERROR</div>
          <div className="verdict-sub">{runError || 'Checks could not complete.'}</div>
        </div>
      );
    }
    if (lastRun?.kind === 'case') {
      return (
        <div className="verdict-sub">
          Single case run. Run all current checks for an aggregate result.
        </div>
      );
    }
    // Suite complete
    if (!report?.results?.length) {
      return (
        <div>
          <div className="verdict-text">ERROR</div>
          <div className="verdict-sub">No results produced.</div>
        </div>
      );
    }
    const total = report.results.length;
    const failed = report.results.filter(r => r.status !== 'PASS').length;
    if (effectiveStatus === 'pass') {
      return (
        <div>
          <div className="verdict-text">PASS</div>
          <div className="verdict-sub">
            {total} of {total} current checks passed across two mapped entry paths.
          </div>
        </div>
      );
    }
    if (effectiveStatus === 'fail') {
      return (
        <div>
          <div className="verdict-text fail">FAIL</div>
          <div className="verdict-sub">
            {failed} of {total} current checks failed.
          </div>
        </div>
      );
    }
    return (
