export default function App() {
  const [status, setStatus]       = useState('idle');      // 'idle'|'running'|'complete'|'error'
  const [lastRun, setLastRun]     = useState(null);         // {kind:'suite'|'case', data}
  const [runError, setRunError]   = useState(null);
  const [selectedKey, setSelectedKey] = useState(null);
  const [pathFilter, setPathFilter]   = useState('all');

  const running = status === 'running';

  // Derive report data
  const report = lastRun?.data ?? null;
  // If runner returned ERROR status, surface it
  const effectiveStatus = (() => {
    if (status === 'error') return 'error';
    if (status !== 'complete') return status;
    if (!report || !Array.isArray(report.results) || report.results.length === 0) return 'error';
    return report.status?.toLowerCase() ?? 'error';
  })();

  // Auto-select first failing/error result after a run
  useEffect(() => {
    if (status !== 'complete' || !report?.results?.length) return;
    const failOrError = report.results.find(r => r.status === 'FAIL' || r.status === 'ERROR');
    if (failOrError) {
      setSelectedKey(failOrError.id);
    } else if (!selectedKey || !report.results.find(r => r.id === selectedKey)) {
      setSelectedKey(report.results[0]?.id ?? null);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [status, report]);

  async function handleRunAll() {
    setStatus('running');
    setRunError(null);
    try {
      const data = runSuite();
      setLastRun({ kind: 'suite', data });
      setStatus('complete');
    } catch (e) {
      setRunError(String(e?.message ?? e));
      setLastRun(null);
      setStatus('error');
    }
  }

  async function handleRunCase(caseSpec, entry) {
    setStatus('running');
    setRunError(null);
    try {
      const result = runCase(caseSpec, entry);
      setLastRun({ kind: 'case', data: { status: result.status, results: [result] } });
      setSelectedKey(result.id);
      setStatus('complete');
    } catch (e) {
      setRunError(String(e?.message ?? e));
      setLastRun(null);
      setStatus('error');
    }
  }

  function handleReset() {
    setStatus('idle');
    setLastRun(null);
    setRunError(null);
    setSelectedKey(null);
  }

  // Verdict
  const verdictEl = (() => {
    if (status === 'idle') {
      return (
        <div className="verdict-idle">
          Not run yet. Checks run in this browser against the fixed sample.
        </div>
      );
    }
    if (status === 'running') {
      return <div className="verdict-idle">Running…</div>;
    }
    if (status === 'error') {
      return (
        <div>
          <div className="verdict-text">ERROR</div>
          <div className="verdict-sub">{runError || 'Checks could not complete.'}</div>
        </div>
      );
    }
    if (lastRun?.kind === 'case') {
      return (
        <div className="verdict-sub">
          Single case run. Run all current checks for an aggregate result.
        </div>
      );
    }
    // Suite complete
    if (!report?.results?.length) {
      return (
        <div>
          <div className="verdict-text">ERROR</div>
          <div className="verdict-sub">No results produced.</div>
        </div>
      );
    }
    const total = report.results.length;
    const failed = report.results.filter(r => r.status !== 'PASS').length;
    if (effectiveStatus === 'pass') {
      return (
        <div>
          <div className="verdict-text">PASS</div>
          <div className="verdict-sub">
            {total} of {total} current checks passed across two mapped entry paths.
          </div>
        </div>
      );
    }
    if (effectiveStatus === 'fail') {
      return (
        <div>
          <div className="verdict-text fail">FAIL</div>
          <div className="verdict-sub">
            {failed} of {total} current checks failed.
          </div>
        </div>
      );
    }
    return (
      <div>
        <div className="verdict-text">ERROR</div>
        <div className="verdict-sub">
          {report.results.find(r => r.status === 'ERROR')?.error ?? 'Unknown error.'}
        </div>
      </div>
    );
  })();

  const logoSrc = `${import.meta.env.BASE_URL}assets/rite-logo-primary-1200.png`;

  return (
    <>
      {/* Header */}
      <header className="header">
        <div className="header-left">
          <img
            src={logoSrc}
            alt="Rite"
            className="header-wordmark"
            width={1200}
            height={300}
          />
          <span className="header-tagline">
            Authorization checks for the paths tests miss.
          </span>
        </div>
        <div className="header-right">A developer workflow for IBM Bob.</div>
      </header>

      {/* Rule band */}
      <div className="rule-band">
        <p className="eyebrow">SAMPLE · SYNTHETIC REFUND SERVICE</p>
        <h1>
          A refund is allowed only when the actor owns the order, the order is
          paid, and it has not already been refunded.
        </h1>
        <p className="rule-sub">
          Allowed: exactly one refund event. Denied: zero events, and the order
          and ledger stay unchanged. Support is another entry path and cannot
          override ownership.
        </p>
        <p className="scope">
          Two mapped entry paths in this sample: customer and support. Paths
          outside this map are not checked. Sample actors and orders are
          simulation, not sign-in.
        </p>
      </div>

      {/* Workbench */}
      <div className="workbench">
        {/* Path map */}
        <PathMap
          pathFilter={pathFilter}
          setPathFilter={setPathFilter}
          lastRun={lastRun}
        />

        {/* Results + verdict */}
        <div className="results-col">
          {/* Verdict */}
          <div className="verdict" role="status" aria-live="polite" aria-atomic="true">
            {verdictEl}
          </div>

          {/* Run controls */}
          <div className="run-controls">
            <button
              className="btn"
              onClick={handleRunAll}
              disabled={running}
              aria-busy={running ? 'true' : undefined}
            >
              {running ? 'Running…' : 'Run all current checks'}
            </button>
            <button
              className="btn btn-secondary"
              onClick={handleReset}
              disabled={running}
            >
              Reset
            </button>
          </div>

          {/* Results table */}
          <ResultsTable
            lastRun={lastRun}
            pathFilter={pathFilter}
            selectedKey={selectedKey}
            setSelectedKey={setSelectedKey}
            onRunCase={handleRunCase}
            running={running}
          />
        </div>

        {/* Case detail */}
        <div className="case-detail-col">
          <CaseDetail selectedKey={selectedKey} lastRun={lastRun} />
        </div>
      </div>

      {/* Recorded proof */}
      <RecordedProof />

      {/* Footer */}
      <footer className="footer">
        Rite is a sample built for the IBM Bob 2.0 Hackathon 2026. It does not
        analyze other repositories and implies no endorsement.
      </footer>
    </>
  );
