  // 2. Effect count — a denial that produces effects is FAIL regardless of decision match
  const observedEffects = Array.isArray(observed.effects) ? observed.effects : [];
  if (observedEffects.length !== exp.effects.length)
    failures.push(
      `effects count: expected ${exp.effects.length}; observed ${observedEffects.length}` +
      (observedEffects.length > 0 ? ` (first: ${JSON.stringify(observedEffects[0])})` : '')
    );

  // 3. Effect content — compare each expected effect structurally
  for (let i = 0; i < exp.effects.length; i++) {
    const eEff = exp.effects[i];
    const oEff = observedEffects[i];
    if (!oEff) break; // already caught by count check
    for (const key of Object.keys(eEff)) {
      if (eEff[key] !== oEff[key])
        failures.push(`effects[${i}].${key}: expected ${JSON.stringify(eEff[key])}; observed ${JSON.stringify(oEff[key])}`);
    }
  }

  // 4. State change
  const observedStateChanged = observed.stateChanged;
  if (observedStateChanged !== exp.stateChanged)
    failures.push(`stateChanged: expected ${exp.stateChanged}; observed ${observedStateChanged}`);

  result.failures = failures;
  result.status = failures.length > 0 ? 'FAIL' : 'PASS';
  return result;
}

