+ * @typedef {{
+ *   version: number,
+ *   ruleId: string,
+ *   rule: string,
+ *   adapter: string,
+ *   paths: Array<{ entry: string, sink: string, source: string }>,
+ *   cases: Array<{
+ *     id: string,
+ *     path: string,
+ *     actor: string,
+ *     input: object,
+ *     expected: {
+ *       decision: 'allow' | 'deny',
+ *       effects: object[],
+ *       stateChanged: boolean,
+ *     }
+ *   }>
