+ * Validate a parsed config object.
+ * Returns an array of error strings (empty = valid).
+ * @param {unknown} config
+ * @returns {string[]}
+ */
+export function validateConfig(config) {
+  const errs = [];
+  if (!config || typeof config !== 'object') {
+    errs.push('config must be an object');
+    return errs;
+  }
