/**
 * src/instrument/auto-adapter.js — Auto-adapter generator.
 *
 * Given a JS/TS module that exports named functions, wraps each target entry
 * and sink with lightweight instrumentation — no code modification needed.
 *
 * How it works:
 *   1. Dynamically imports the target module.
 *   2. Wraps named entry functions to capture call arguments.
 *   3. Wraps the named sink function to record every invocation.
 *   4. Exposes runCase(caseSpec) using the same adapter contract as rite.adapter.mjs.
 *
 * Limitations:
 *   - Works for ES modules and CJS modules with named exports.
 *   - The sink must be exported OR accessible via a state object returned by a factory.
 *   - Does not handle async generator patterns or prototype-chain dispatch.
 *   - Does not instrument code behind dynamic require() or conditional imports.
 *   - For complex services (dependency injection, class hierarchies), a manual
 *     adapter is still recommended.
 *
 * Usage (programmatic):
 *   import { generateAdapter } from './auto-adapter.js';
 *   const adapter = await generateAdapter({
 *     modulePath: './src/service.js',
 *     factoryFn: 'createService',   // optional: if module exports a factory
 *     factoryArgs: [{ orders: [...] }],
 *     entries: ['customerRefund', 'supportRefund'],
 *     sink: 'issueRefund',          // name to detect in call stack / exports
 *     snapshotFn: 'snapshot',       // optional: for before/after state
 *   });
 *   const report = await verify(config, adapter);
 *
 * Usage (CLI):
 *   rite instrument --module ./src/service.js \
 *                   --factory createService \
 *                   --entries customerRefund,supportRefund \
 *                   --sink issueRefund \
 *                   --snapshot snapshot \
 *                   --out examples/generated/rite.adapter.mjs
 */

import { pathToFileURL } from 'node:url';
import { writeFileSync } from 'node:fs';

// ------------------------------------------------------------------ //
// Effect schema registry                                               //
// ------------------------------------------------------------------ //
// Registered sink schemas validate that effects match before comparison.
// See src/instrument/effect-schema.js for the full registry.

/**
 * @typedef {{
 *   modulePath: string,
 *   factoryFn?: string,
 *   factoryArgs?: unknown[],
 *   entries: string[],
 *   sink: string,
 *   snapshotFn?: string,
 *   seedBuilder?: (caseSpec: object) => object[],
 * }} InstrumentOptions
 */

/**
 * Generate a live adapter object (not a file) by wrapping a loaded module.
 * @param {InstrumentOptions} opts
 * @returns {Promise<{ runCase: (caseSpec: object) => Promise<object> }>}
 */
export async function generateAdapter(opts) {
  const { modulePath, factoryFn, factoryArgs = [], entries, sink, snapshotFn, seedBuilder } = opts;

  const mod = await import(pathToFileURL(modulePath).href);

  return {
    /**
     * runCase — conforms to the rite adapter contract.
     */
    async runCase(caseSpec) {
      const { path: entryName, actor, input } = caseSpec;

      if (!entries.includes(entryName)) {
        throw new Error(`Entry "${entryName}" not in instrumented entries: ${entries.join(', ')}`);
      }

      // Build fixture args — use seedBuilder if provided, else empty
      const seeds = seedBuilder ? seedBuilder(caseSpec) : [];

      // Create a fresh service instance per case
      let instance;
      const capturedSinkCalls = [];

      if (factoryFn) {
        const factory = mod[factoryFn];
        if (typeof factory !== 'function')
          throw new Error(`Factory "${factoryFn}" not found in module`);
        instance = factory(...(seeds.length ? [{ orders: seeds }, ...factoryArgs.slice(1)] : factoryArgs));
      } else {
        // Module-level exports: wrap directly
        instance = mod;
      }

      // Wrap the sink to capture calls
      const originalSink = instance[sink];
      if (typeof originalSink === 'function') {
        instance[sink] = function (...args) {
          const result = originalSink.apply(this, args);
          capturedSinkCalls.push({ args, result });
          return result;
        };
      }
      // Note: if sink is a private closure (most common case), use snapshotFn to infer effects.

      const entryFn = instance[entryName];
      if (typeof entryFn !== 'function')
        throw new Error(`Entry "${entryName}" not found on instance`);

      // Snapshot before
      const snapshotBefore = snapshotFn && typeof instance[snapshotFn] === 'function'
        ? instance[snapshotFn]()
        : null;
      const eventsBefore = snapshotBefore?.events?.length ?? 0;

      // Call entry
      const result = entryFn.call(instance, input, { actorId: actor });

      // Snapshot after
      const snapshotAfter = snapshotFn && typeof instance[snapshotFn] === 'function'
        ? instance[snapshotFn]()
        : null;
      const eventsAfter = snapshotAfter?.events?.length ?? 0;

      // Derive effects from snapshot delta (works for private sinks)
      const newEvents = snapshotAfter?.events
        ? snapshotAfter.events.slice(eventsBefore)
        : capturedSinkCalls.map(c => c.args[0] ?? c.args);

      const effects = newEvents.map(({ refundId: _rid, ...rest }) => rest);

      const orderId = input?.orderId;
      const stateBefore = snapshotBefore?.orders?.find(o => o.id === orderId) ?? null;
      const stateAfter  = snapshotAfter?.orders?.find(o => o.id === orderId) ?? null;
      const stateChanged = JSON.stringify(stateBefore) !== JSON.stringify(stateAfter);

      return {
        decision: result?.ok === true ? 'allow' : 'deny',
        effects,
        stateBefore,
        stateAfter,
        stateChanged,
      };
    },
  };
}

// ------------------------------------------------------------------ //
// File generator — write a static adapter file                        //
// ------------------------------------------------------------------ //

/**
 * Generate and write a rite.adapter.mjs file for a given module.
 * The generated file is a fully self-contained adapter that can be committed.
 * @param {InstrumentOptions & { outPath: string, relativeModulePath: string }} opts
 */
export function writeAdapterFile(opts) {
  const { entries, sink, snapshotFn, factoryFn, outPath, relativeModulePath } = opts;

  const importLine = factoryFn
    ? `import { ${factoryFn} } from '${relativeModulePath}';`
    : `import * as mod from '${relativeModulePath}';`;

  const instanceExpr = factoryFn
    ? `${factoryFn}({ orders: seedsForCase(input.orderId) })`
    : `mod`;

  const snapshotBefore = snapshotFn
    ? `const snapBefore = instance.${snapshotFn}();`
    : `const snapBefore = { events: [], orders: [] };`;

  const snapshotAfter = snapshotFn
    ? `const snapAfter = instance.${snapshotFn}();`
    : `const snapAfter = { events: [], orders: [] };`;

  const entryDispatch = entries.map(e =>
    `  if (entryName === '${e}') result = instance.${e}(input, { actorId: actor });`
  ).join('\n');

  const content = `/**
 * rite.adapter.mjs — Auto-generated by \`rite instrument\`.
 * Edit seed definitions and the SEEDS map to match your fixtures.
 * Generated: ${new Date().toISOString()}
 */

${importLine}

// TODO: populate SEEDS with your fixture data.
const SEEDS = {
  'example-id': {
    id: 'example-id',
    ownerId: 'actor-owner',
    paymentStatus: 'paid',
    amountCents: 1000,
    currency: 'USD',
    refunded: false,
  },
};

function seedsForCase(resourceId) {
  const seed = SEEDS[resourceId];
  if (!seed) throw new Error(\`No seed for: \${resourceId}\`);
  return [{ ...seed }];
}

export async function runCase(caseSpec) {
  const { path: entryName, actor, input } = caseSpec;
  const instance = ${instanceExpr};
  ${snapshotBefore}
  let result;
${entryDispatch}
  else throw new Error(\`Unknown entry: \${entryName}\`);
  ${snapshotAfter}
  const newEvents = snapAfter.events.slice(snapBefore.events.length);
  const effects = newEvents.map(({ refundId: _rid, ...rest }) => rest);
  const orderId = input?.orderId ?? input?.resourceId;
  const stateBefore = snapBefore.orders?.find(o => o.id === orderId) ?? null;
  const stateAfter  = snapAfter.orders?.find(o => o.id === orderId) ?? null;
  const stateChanged = JSON.stringify(stateBefore) !== JSON.stringify(stateAfter);
  return {
    decision: result?.ok === true ? 'allow' : 'deny',
    effects,
    stateBefore,
    stateAfter,
    stateChanged,
  };
}
`;

  writeFileSync(outPath, content, 'utf-8');
}

/**
 * src/instrument/effect-schema.js — Typed effect registry.
 *
 * Defines named sink event schemas. The engine validates adapter-reported
 * effects against the registered schema before structural comparison.
 * This prevents two adapters describing the same event differently from
 * both passing silently.
 *
 * Schema format:
 *   { field: 'type' | ['type', required?] }
 * Types: 'string' | 'number' | 'boolean' | 'object' | 'any'
 *
 * Register your schema in rite.config.json under "effectSchema":
 *   "effectSchema": "refund-event"
 *
 * Or inline in config:
 *   "effectSchema": {
 *     "orderId":    "string",
 *     "actorId":    "string",
 *     "amountCents": "number",
 *     "currency":   "string"
 *   }
 */

// ------------------------------------------------------------------ //
// Built-in schemas                                                     //
// ------------------------------------------------------------------ //

/** @type {Record<string, Record<string, string | [string, boolean]>>} */
const BUILT_IN_SCHEMAS = {
  'refund-event': {
    orderId:     'string',
    actorId:     'string',
    amountCents: 'number',
    currency:    'string',
  },
  'transfer-event': {
    fromAccountId: 'string',
    toAccountId:   'string',
    amountCents:   'number',
    currency:      'string',
  },
  'permission-grant': {
    subjectId:   'string',
    resourceId:  'string',
    permission:  'string',
    grantedBy:   'string',
  },
};

// ------------------------------------------------------------------ //
// Validator                                                            //
// ------------------------------------------------------------------ //

/**
 * Resolve a schema from either a registered name or an inline object.
 * @param {string | Record<string,string> | undefined} schemaRef
 * @returns {Record<string,string> | null}
 */
export function resolveSchema(schemaRef) {
  if (!schemaRef) return null;
  if (typeof schemaRef === 'string') return BUILT_IN_SCHEMAS[schemaRef] ?? null;
  if (typeof schemaRef === 'object') return schemaRef;
  return null;
}

/**
 * Validate one effect object against a schema.
 * Returns an array of violation strings (empty = valid).
 * @param {object} effect
 * @param {Record<string,string>} schema
 * @param {string} context — for error messages
 * @returns {string[]}
 */
export function validateEffect(effect, schema, context = 'effect') {
  const violations = [];
  for (const [field, typeSpec] of Object.entries(schema)) {
    const [expectedType, required = true] = Array.isArray(typeSpec) ? typeSpec : [typeSpec, true];
    const value = /** @type {Record<string,unknown>} */ (effect)[field];
    if (value === undefined || value === null) {
      if (required) violations.push(`${context}.${field}: required field missing`);
      continue;
    }
    if (expectedType === 'any') continue;
    const actualType = typeof value;
    if (actualType !== expectedType)
      violations.push(`${context}.${field}: expected ${expectedType}; got ${actualType} (${JSON.stringify(value)})`);
  }
  // Reject unknown fields — adapters must not smuggle extra data
  for (const key of Object.keys(effect)) {
    if (!(key in schema))
      violations.push(`${context}.${key}: unexpected field not in schema`);
  }
  return violations;
}

/**
 * Validate all effects in a case result against the config schema.
 * Returns all violations across all effects.
 * @param {object[]} effects
 * @param {string | Record<string,string> | undefined} schemaRef
 * @returns {string[]}
 */
export function validateEffects(effects, schemaRef) {
  const schema = resolveSchema(schemaRef);
  if (!schema || !Array.isArray(effects)) return [];
  const violations = [];
  for (let i = 0; i < effects.length; i++) {
    violations.push(...validateEffect(effects[i], schema, `effects[${i}]`));
  }
  return violations;
}

/** @returns {string[]} Names of all built-in schemas */
export function listSchemas() {
  return Object.keys(BUILT_IN_SCHEMAS);
}

/**
 * src/graph/walker.js — Lightweight JS call-graph walker.
 *
 * Traces call paths from named entry functions to a named sink within
 * a single JS/TS file using regex-based heuristics. Not a full AST parser —
 * it reads function bodies and detects direct function calls by name.
 *
 * Limitations (stated explicitly):
 *   - Single-file scope only; does not follow cross-file imports.
 *   - Detects direct named calls: foo(), this.foo(), self.foo().
 *   - Does not resolve aliases, computed calls, prototype chains, or closures
 *     unless the called name literally appears in the source.
 *   - Works well for module-pattern code (factory functions with closures).
 *   - For large multi-file codebases, use a proper AST tool (acorn, ts-morph).
 *
 * Returns a PathTrace suitable for docs/path-map.md generation.
 */

import { readFileSync } from 'node:fs';

// ------------------------------------------------------------------ //
// Source reader                                                        //
// ------------------------------------------------------------------ //

/**
 * Extract named function/method bodies from JS source.
 * Handles: function foo() {}, const foo = function() {}, const foo = () => {},
 * foo(...) { ... } (method shorthand), async variants.
 * @param {string} source
 * @returns {Map<string, { body: string, startLine: number }>}
 */
function extractFunctions(source) {
  const fns = new Map();
  const lines = source.split('\n');

  // Pattern: function name(...) { OR const name = (...) => { OR async function name
  const funcPattern = /(?:async\s+)?function\s+(\w+)\s*\(/g;
  const arrowPattern = /(?:const|let|var)\s+(\w+)\s*=\s*(?:async\s+)?\(?[^)]*\)?\s*=>/g;
  const methodPattern = /^\s*(?:async\s+)?(\w+)\s*\([^)]*\)\s*\{/gm;

  for (const [pattern, nameIdx] of [
    [funcPattern, 1],
    [arrowPattern, 1],
    [methodPattern, 1],
  ]) {
    let match;
    while ((match = pattern.exec(source)) !== null) {
      const name = match[nameIdx];
      if (!name || fns.has(name)) continue;
      // Find the line number
      const upTo = source.slice(0, match.index);
      const startLine = upTo.split('\n').length;
      // Extract body: find matching braces from match position
      const bodyStart = source.indexOf('{', match.index);
      if (bodyStart === -1) continue;
      let depth = 0;
      let bodyEnd = bodyStart;
      for (let i = bodyStart; i < source.length; i++) {
        if (source[i] === '{') depth++;
        else if (source[i] === '}') {
          depth--;
          if (depth === 0) { bodyEnd = i; break; }
        }
      }
      fns.set(name, { body: source.slice(bodyStart, bodyEnd + 1), startLine });
    }
  }
  return fns;
}

/**
 * Find all function names called inside a function body.
 * @param {string} body
 * @returns {string[]}
 */
function findCalls(body) {
  const calls = new Set();
  // Match: word( OR this.word( OR self.word(
  const callPattern = /(?:this\.|self\.)?(\w+)\s*\(/g;
  let m;
  while ((m = callPattern.exec(body)) !== null) {
    const name = m[1];
    // Filter out JS keywords and common built-ins
    if (!['if', 'for', 'while', 'switch', 'catch', 'new', 'return', 'typeof',
          'instanceof', 'await', 'async', 'function', 'class', 'import',
          'console', 'Object', 'Array', 'String', 'Number', 'Promise',
          'Error', 'Map', 'Set', 'JSON', 'Math'].includes(name)) {
      calls.add(name);
    }
  }
  return [...calls];
}

// ------------------------------------------------------------------ //
// Path trace                                                           //
// ------------------------------------------------------------------ //

/**
 * @typedef {{
 *   entry: string,
 *   sink: string,
 *   path: string[],      // function call chain entry → … → sink
 *   found: boolean,
 *   startLine: number,
 * }} PathTrace
 */

/**
 * BFS from entry toward sink, using extracted function bodies.
 * @param {string} entry
 * @param {string} sink
 * @param {Map<string, { body: string, startLine: number }>} fns
 * @returns {PathTrace}
 */
function tracePath(entry, sink, fns) {
  const entryInfo = fns.get(entry);
  if (!entryInfo) return { entry, sink, path: [entry], found: false, startLine: 0 };

  // BFS
  const queue = [[entry]];
  const visited = new Set([entry]);

  while (queue.length > 0) {
    const currentPath = queue.shift();
    const current = currentPath[currentPath.length - 1];
    const fnInfo = fns.get(current);
    if (!fnInfo) continue;

    const calls = findCalls(fnInfo.body);
    for (const called of calls) {
      if (called === sink) {
        return {
          entry,
          sink,
          path: [...currentPath, sink],
          found: true,
          startLine: entryInfo.startLine,
        };
      }
      if (!visited.has(called) && fns.has(called)) {
        visited.add(called);
        queue.push([...currentPath, called]);
      }
    }
  }

  return { entry, sink, path: [entry], found: false, startLine: entryInfo.startLine };
}

// ------------------------------------------------------------------ //
// Public API                                                           //
// ------------------------------------------------------------------ //

/**
 * @typedef {{
 *   file: string,
 *   entries: string[],
 *   sink: string,
 *   traces: PathTrace[],
 *   functions: string[],
 *   note: string,
 * }} WalkResult
 */

/**
 * Walk a JS file and trace all named entry paths to a sink.
 * @param {{ file: string, entries: string[], sink: string }} opts
 * @returns {WalkResult}
 */
export function walkFile({ file, entries, sink }) {
  const source = readFileSync(file, 'utf-8');
  const fns = extractFunctions(source);
  const traces = entries.map(entry => tracePath(entry, sink, fns));
  return {
    file,
    entries,
    sink,
    traces,
    functions: [...fns.keys()],
    note: 'Regex-based single-file walker. Does not follow cross-file imports or resolve aliases.',
  };
}

/**
 * Format a WalkResult as Markdown for docs/path-map.md.
 * @param {WalkResult} result
 * @returns {string}
 */
export function formatWalkResult(result) {
  const lines = [];
  lines.push(`## Auto-discovered paths in \`${result.file}\``);
  lines.push('');
  lines.push(`> ${result.note}`);
  lines.push('');

  for (const trace of result.traces) {
    const status = trace.found ? '✓ reaches sink' : '✗ no path to sink found';
    lines.push(`### \`${trace.entry}\` → \`${trace.sink}\`  (${status})`);
    if (trace.found) {
      lines.push('');
      lines.push('Call chain:');
      lines.push('```');
      lines.push(trace.path.join(' → '));
      lines.push('```');
    } else {
      lines.push('');
      lines.push('No direct call chain detected. The sink may be reached via a closure,');
      lines.push('dynamic dispatch, or a cross-file import outside this walker\'s scope.');
    }
    lines.push('');
  }

  lines.push('### All functions detected');
  lines.push('');
  for (const fn of result.functions) {
    const reachesSink = result.traces.some(t => t.path.includes(fn) && t.found);
    lines.push(`- \`${fn}\`${reachesSink ? '  ← on path to sink' : ''}`);
  }
  return lines.join('\n');
}

/**
 * src/core/sarif.js — SARIF 2.1.0 output formatter.
 *
 * Converts a Rite VerifyReport into a SARIF document suitable for upload
 * to GitHub Code Scanning via `actions/upload-sarif`.
 *
 * Spec: https://docs.oasis-open.org/sarif/sarif/v2.1.0/sarif-v2.1.0.html
 * GitHub upload: https://docs.github.com/en/code-security/code-scanning/integrating-with-code-scanning/uploading-a-sarif-file-to-github
 *
 * Usage:
 *   rite verify --config rite.config.json --sarif results.sarif
 *
 * SARIF level mapping:
 *   FAIL  → error   (blocks merge when uploaded as a required check)
 *   ERROR → error
 *   PASS  → note    (informational, does not block)
 */

import { ENGINE_VERSION } from './engine.js';

const SARIF_SCHEMA = 'https://raw.githubusercontent.com/oasis-tcs/sarif-spec/master/Schemata/sarif-schema-2.1.0.json';
const SARIF_VERSION = '2.1.0';

/**
 * @typedef {import('./engine.js').VerifyReport} VerifyReport
 * @typedef {import('./engine.js').CaseResult} CaseResult
 */

/**
 * Map a case status to a SARIF notification level.
 * @param {'PASS'|'FAIL'|'ERROR'} status
 * @returns {'error'|'warning'|'note'}
 */
function toLevel(status) {
  if (status === 'PASS') return 'note';
  return 'error';
}

/**
 * Build a SARIF result for one case.
 * @param {CaseResult} r
 * @param {string} ruleId
 * @returns {object}
 */
function buildResult(r, ruleId) {
  const level = toLevel(r.status);
  const message = r.status === 'PASS'
    ? `${r.id}: authorization check passed on path "${r.path}".`
    : r.status === 'ERROR'
      ? `${r.id}: case execution error on path "${r.path}": ${r.error?.split('\n')[0]}`
      : `${r.id}: authorization check FAILED on path "${r.path}". ${r.failures.join(' | ')}`;

  return {
    ruleId,
    level,
    message: { text: message },
    locations: [
      {
        physicalLocation: {
          artifactLocation: {
            uri: r.observed?.sourceFile ?? 'src/refunds.js',
            uriBaseId: '%SRCROOT%',
          },
        },
        logicalLocations: [
          { name: r.path, kind: 'function' },
        ],
      },
    ],
    partialFingerprints: {
      'rite/caseId': r.id,
      'rite/path': r.path,
    },
  };
}

/**
 * Convert a VerifyReport to a SARIF 2.1.0 document.
 * @param {VerifyReport} report
 * @returns {object} — serialize with JSON.stringify
 */
export function toSarif(report) {
  const ruleId = report.ruleId ?? 'rite-authorization';

  const rules = [
    {
      id: ruleId,
      name: 'RiteAuthorizationCheck',
      shortDescription: { text: report.rule ?? 'Authorization rule check' },
      fullDescription: {
        text: `Rite checks that the written authorization rule holds across all configured entry paths. Rule: ${report.rule}`,
      },
      defaultConfiguration: { level: 'error' },
      helpUri: 'https://github.com/timidan/rite',
      properties: {
        tags: ['security', 'authorization', 'access-control'],
        precision: 'high',
        'security-severity': '8.0',  // CVSS-style; IDOR is typically 7-9
      },
    },
  ];

  const results = (report.results ?? []).map(r => buildResult(r, ruleId));

  return {
    $schema: SARIF_SCHEMA,
    version: SARIF_VERSION,
    runs: [
      {
        tool: {
          driver: {
            name: 'Rite',
            version: ENGINE_VERSION,
            informationUri: 'https://github.com/timidan/rite',
            rules,
          },
        },
        results,
        automationDetails: {
          id: `rite/${report.ruleId ?? 'check'}/${report.generatedAt}`,
        },
        columnKind: 'utf16CodeUnits',
      },
    ],
  };
}

/**
 * src/watsonx/draft.js — watsonx.ai case and path drafting.
 *
 * Sends a rule + limited code snippet to IBM watsonx.ai (via the chat API)
 * and returns a candidate config diff for developer review.
 *
 * Authentication: IBM Cloud IAM API key → bearer token exchange.
 * The token is never written to disk or logged.
 *
 * Environment variables (never passed to verify; server-side only):
 *   IBMCLOUD_API_KEY     — IBM Cloud IAM API key
 *   WATSONX_PROJECT_ID   — watsonx.ai project ID
 *   WATSONX_REGION       — e.g. us-south (default)
 *   WATSONX_MODEL_ID     — e.g. ibm/granite-3-3-8b-instruct (checked at runtime)
 *
 * If any credential is absent, draftCases() returns { available: false, reason }.
 * The caller must display this state and never show a mocked response as live.
 *
 * API reference: https://cloud.ibm.com/docs/apis/watsonx-ai
 */

const IAM_TOKEN_URL = 'https://iam.cloud.ibm.com/identity/token';
const DEFAULT_REGION = 'us-south';

// ------------------------------------------------------------------ //
// IAM token exchange                                                   //
// ------------------------------------------------------------------ //

/**
 * Exchange an IBM Cloud API key for a short-lived bearer token.
 * @param {string} apiKey
 * @returns {Promise<string>} access token
 */
async function getIamToken(apiKey) {
  const body = new URLSearchParams({
    grant_type: 'urn:ibm:params:oauth:grant-type:apikey',
    apikey: apiKey,
  });

  const resp = await fetch(IAM_TOKEN_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: body.toString(),
  });

  if (!resp.ok) {
    const text = await resp.text().catch(() => '');
    throw new Error(`IAM token exchange failed (${resp.status}): ${text.slice(0, 200)}`);
  }

  const data = await resp.json();
  if (!data.access_token) throw new Error('IAM response missing access_token');
  return data.access_token;
}

// ------------------------------------------------------------------ //
// Model listing — verify entitlement at runtime                       //
// ------------------------------------------------------------------ //

/**
 * List available foundation models in the project.
 * Returns the first Granite text model found, or null.
 * @param {string} token
 * @param {string} projectId
 * @param {string} region
 * @returns {Promise<string|null>}
 */
async function resolveModelId(token, projectId, region) {
  const url = `https://${region}.ml.cloud.ibm.com/ml/v1/foundation_model_specs?version=2024-09-16&limit=50`;
  try {
    const resp = await fetch(url, {
      headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
    });
    if (!resp.ok) return null;
    const data = await resp.json();
    const models = data.resources ?? [];
    // Prefer a granite instruct model
    const granite = models.find(m =>
      m.model_id?.includes('granite') && m.model_id?.includes('instruct')
    );
    return granite?.model_id ?? models[0]?.model_id ?? null;
  } catch {
    return null;
  }
}

// ------------------------------------------------------------------ //
// Prompt construction                                                  //
// ------------------------------------------------------------------ //

/**
 * Build the prompt asking watsonx for candidate config entries.
 * Sends ONLY the rule and explicitly selected code snippet (size-limited).
 * @param {string} rule
 * @param {string} snippet  — public/synthetic only, reviewed before sending
 * @returns {string}
 */
function buildPrompt(rule, snippet) {
  return `You are helping a developer configure an authorization verification tool called Rite.

The developer has written this authorization rule:
"${rule}"

Here is a limited code snippet from their service (synthetic/public data only):
\`\`\`js
${snippet.slice(0, 2000)}
\`\`\`

Please identify:
1. Candidate entry point function names that could reach a sensitive operation.
2. The likely sink function name (the sensitive operation).
3. Three to five test cases: at least one that should be ALLOWED and at least two that should be DENIED (with different denial reasons).
4. For each case: a unique ID, which entry path, a test actor ID, a minimal input object, expected decision (allow/deny), and a brief reason.

IMPORTANT:
- Only cite functions that appear in the snippet above. Label anything inferred as a hypothesis.
- Do not invent actors, amounts, or resource IDs beyond what the snippet implies.
- Return ONLY valid JSON matching this schema (no prose, no markdown fences):

{
  "hypothesis": true,
  "paths": [
    { "entry": "functionName", "sink": "sinkName", "source": "filename.js" }
  ],
  "cases": [
    {
      "id": "case-id",
      "path": "entryFunctionName",
      "actor": "actor-id",
      "input": { "resourceId": "resource-1" },
      "expected": { "decision": "allow|deny", "effects": [], "stateChanged": false },
      "reason": "One sentence."
    }
  ]
}`;
}

// ------------------------------------------------------------------ //
// Main draft function                                                  //
// ------------------------------------------------------------------ //

/**
 * @typedef {{
 *   available: true,
 *   modelId: string,
 *   hypothesis: true,
 *   paths: object[],
 *   cases: object[],
 *   rawResponse: string,
 * } | {
 *   available: false,
 *   reason: string,
 * }} DraftResult
 */

/**
 * Call watsonx.ai to draft candidate paths and cases from a rule + snippet.
 * Returns available:false when credentials are missing or the call fails.
 * Never throws — errors are returned as available:false with a reason.
 *
 * @param {{ rule: string, snippet: string }} opts
 * @returns {Promise<DraftResult>}
 */
export async function draftCases({ rule, snippet }) {
  const apiKey     = process.env.IBMCLOUD_API_KEY;
  const projectId  = process.env.WATSONX_PROJECT_ID;
  const region     = process.env.WATSONX_REGION ?? DEFAULT_REGION;
  const modelIdEnv = process.env.WATSONX_MODEL_ID;

  if (!apiKey)    return { available: false, reason: 'IBMCLOUD_API_KEY not set' };
  if (!projectId) return { available: false, reason: 'WATSONX_PROJECT_ID not set' };

  let token;
  try {
    token = await getIamToken(apiKey);
  } catch (e) {
    return { available: false, reason: `IAM auth failed: ${e.message}` };
  }

  // Resolve model at runtime — do not guess a model ID
  const modelId = modelIdEnv ?? await resolveModelId(token, projectId, region);
  if (!modelId) {
    return { available: false, reason: 'No foundation model available in this project. Set WATSONX_MODEL_ID or check project entitlements.' };
  }

  const prompt = buildPrompt(rule, snippet);
  const url = `https://${region}.ml.cloud.ibm.com/ml/v1/text/chat?version=2024-09-16`;

  let rawResponse;
  try {
    const resp = await fetch(url, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${token}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        model_id: modelId,
        project_id: projectId,
        messages: [{ role: 'user', content: prompt }],
        parameters: {
          max_new_tokens: 1200,
          temperature: 0.2,
        },
      }),
    });

    if (!resp.ok) {
      const text = await resp.text().catch(() => '');
      return { available: false, reason: `watsonx API error (${resp.status}): ${text.slice(0, 300)}` };
    }

    const data = await resp.json();
    rawResponse = data?.results?.[0]?.generated_text
      ?? data?.choices?.[0]?.message?.content
      ?? JSON.stringify(data);
  } catch (e) {
    return { available: false, reason: `Network error calling watsonx: ${e.message}` };
  }

  // Parse response — treat as untrusted
  let parsed;
  try {
    // Strip markdown fences if present
    const cleaned = rawResponse.replace(/^```(?:json)?\s*/m, '').replace(/\s*```\s*$/m, '').trim();
    parsed = JSON.parse(cleaned);
  } catch {
    return { available: false, reason: `watsonx returned non-JSON response. Raw: ${rawResponse.slice(0, 300)}` };
  }

  // Validate required fields
  if (!Array.isArray(parsed.paths) || !Array.isArray(parsed.cases)) {
    return { available: false, reason: 'watsonx response missing paths or cases arrays. Check prompt and model.' };
  }

  // Verify all path/case citations are in the snippet
  for (const p of parsed.paths) {
    if (typeof p.entry === 'string' && !snippet.includes(p.entry)) {
      // Label as unverified hypothesis rather than reject
      p.hypothesis = true;
    }
  }

  return {
    available: true,
    modelId,
    hypothesis: true,  // Always label model output as hypothesis
    paths: parsed.paths,
    cases: parsed.cases,
    rawResponse,
  };
}

/**
 * src/instrument/effect-schema.js — Typed effect registry.
 *
 * Defines named sink event schemas. The engine validates adapter-reported
 * effects against the registered schema before structural comparison.
 * This prevents two adapters describing the same event differently from
 * both passing silently.
 *
 * Schema format:
 *   { field: 'type' | ['type', required?] }
 * Types: 'string' | 'number' | 'boolean' | 'object' | 'any'
 *
 * Register your schema in rite.config.json under "effectSchema":
 *   "effectSchema": "refund-event"
 *
 * Or inline in config:
 *   "effectSchema": {
 *     "orderId":    "string",
 *     "actorId":    "string",
 *     "amountCents": "number",
 *     "currency":   "string"
 *   }
 */

// ------------------------------------------------------------------ //
// Built-in schemas                                                     //
// ------------------------------------------------------------------ //

/** @type {Record<string, Record<string, string | [string, boolean]>>} */
const BUILT_IN_SCHEMAS = {
  'refund-event': {
    orderId:     'string',
    actorId:     'string',
    amountCents: 'number',
    currency:    'string',
  },
  'transfer-event': {
    fromAccountId: 'string',
    toAccountId:   'string',
    amountCents:   'number',
    currency:      'string',
  },
  'permission-grant': {
    subjectId:   'string',
    resourceId:  'string',
    permission:  'string',
    grantedBy:   'string',
  },
};

// ------------------------------------------------------------------ //
// Validator                                                            //
// ------------------------------------------------------------------ //

/**
 * Resolve a schema from either a registered name or an inline object.
 * @param {string | Record<string,string> | undefined} schemaRef
