/**
 * src/github/app.js — GitHub App server scaffold.
 *
 * Handles:
 *   GET  /github/login          — Start OAuth flow
 *   GET  /github/callback       — OAuth callback, set session
 *   GET  /github/installations  — List repos the user authorised
 *   GET  /github/runs           — List recent Rite workflow runs for a repo
 *   GET  /github/report         — Fetch and validate a run's Rite report artifact
 *   POST /github/logout         — Clear session
 *
 * Security model:
 *   - User access token (user-to-server) for identity and session.
 *   - Short-lived installation token (server-to-server) for artifact reads.
 *   - App private key and session secret are environment variables — never
 *     in browser assets, GitHub Actions logs, or Rite report JSON.
 *   - Repository owner/name is NEVER trusted from a browser query parameter;
 *     only repos in the user's authenticated installation list are served.
 *   - Report schema and embedded SHA are validated against GitHub run metadata
 *     before display. Mismatch → explicit error state, never PASS.
 *
 * Environment variables required:
 *   GITHUB_APP_ID          — numeric App ID from GitHub App settings
 *   GITHUB_APP_CLIENT_ID   — OAuth client ID
 *   GITHUB_APP_CLIENT_SECRET
 *   GITHUB_APP_PRIVATE_KEY — PEM key, newlines as \n
 *   RITE_SESSION_SECRET    — Random 32+ char string for session signing
 *   RITE_PUBLIC_URL        — e.g. https://rite.example.com (for OAuth callback)
 *
 * Status: SCAFFOLD — routes are defined and documented but the server is not
 * started automatically. Register your GitHub App at github.com/settings/apps
 * and set the environment variables above before enabling.
 *
 * GitHub App docs: https://docs.github.com/en/apps
 */

// ------------------------------------------------------------------ //
// Dependency check — these must be installed to use the GitHub server //
// ------------------------------------------------------------------ //
// npm install @octokit/app @octokit/oauth-app express express-session
// They are NOT installed by default — kept out of the base bundle.
// ------------------------------------------------------------------ //

/**
 * Check required environment variables.
 * @returns {{ ok: boolean, missing: string[] }}
 */
export function checkEnv() {
  const required = [
    'GITHUB_APP_ID',
    'GITHUB_APP_CLIENT_ID',
    'GITHUB_APP_CLIENT_SECRET',
    'GITHUB_APP_PRIVATE_KEY',
    'RITE_SESSION_SECRET',
    'RITE_PUBLIC_URL',
  ];
  const missing = required.filter(k => !process.env[k]);
  return { ok: missing.length === 0, missing };
}

/**
 * Build the GitHub App OAuth authorization URL.
 * @param {string} state — CSRF token, stored in session
 * @returns {string}
 */
export function buildAuthUrl(state) {
  const clientId = process.env.GITHUB_APP_CLIENT_ID ?? '';
  const redirectUri = encodeURIComponent(`${process.env.RITE_PUBLIC_URL}/github/callback`);
  return `https://github.com/login/oauth/authorize?client_id=${clientId}&redirect_uri=${redirectUri}&state=${state}&scope=read:user`;
}

/**
 * Exchange a GitHub OAuth code for a user access token.
 * @param {string} code
 * @returns {Promise<{ token: string, tokenType: string }>}
 */
export async function exchangeCode(code) {
  const resp = await fetch('https://github.com/login/oauth/access_token', {
    method: 'POST',
    headers: { Accept: 'application/json', 'Content-Type': 'application/json' },
    body: JSON.stringify({
      client_id: process.env.GITHUB_APP_CLIENT_ID,
      client_secret: process.env.GITHUB_APP_CLIENT_SECRET,
      code,
    }),
  });
  if (!resp.ok) throw new Error(`GitHub token exchange failed: ${resp.status}`);
  const data = await resp.json();
  if (data.error) throw new Error(`GitHub OAuth error: ${data.error_description ?? data.error}`);
  return { token: data.access_token, tokenType: data.token_type };
}

/**
 * List repositories accessible to the authenticated user via their installations.
 * Uses the user access token — only repos the user authorised appear here.
 * @param {string} userToken — user access token
 * @returns {Promise<Array<{ id: number, fullName: string, installationId: number }>>}
 */
export async function listAuthorizedRepos(userToken) {
  // 1. Get installations this user has authorised
  const instResp = await fetch('https://api.github.com/user/installations', {
    headers: {
      Authorization: `Bearer ${userToken}`,
      Accept: 'application/vnd.github+json',
      'X-GitHub-Api-Version': '2022-11-28',
    },
  });
  if (!instResp.ok) throw new Error(`GitHub installations list failed: ${instResp.status}`);
  const instData = await instResp.json();
  const installations = instData.installations ?? [];

  // 2. For each installation, list repos — filter to Rite-relevant ones
  const allRepos = [];
  for (const inst of installations) {
    const repoResp = await fetch(
      `https://api.github.com/user/installations/${inst.id}/repositories`,
      {
        headers: {
          Authorization: `Bearer ${userToken}`,
          Accept: 'application/vnd.github+json',
          'X-GitHub-Api-Version': '2022-11-28',
        },
      }
    );
    if (!repoResp.ok) continue;
    const repoData = await repoResp.json();
    for (const repo of repoData.repositories ?? []) {
      allRepos.push({ id: repo.id, fullName: repo.full_name, installationId: inst.id });
    }
  }
  return allRepos;
}

/**
 * Get a short-lived installation token for artifact reads.
 * Uses the App private key — never exposed to the browser.
 * @param {number} installationId
 * @returns {Promise<string>} installation access token
 */
export async function getInstallationToken(installationId) {
  // JWT signing requires @octokit/auth-app or manual jwt construction.
  // Placeholder — implement after registering the App and installing octokit.
  throw new Error(
    'getInstallationToken: install @octokit/auth-app and set GITHUB_APP_PRIVATE_KEY. ' +
    'See: https://docs.github.com/en/apps/creating-github-apps/authenticating-with-a-github-app/generating-an-installation-access-token-for-a-github-app'
  );
}

/**
 * List recent workflow runs for a repo that have a Rite report artifact.
 * Verifies the repo is in the user's authorised list before fetching.
 * @param {string} userToken
 * @param {number} repoId  — from listAuthorizedRepos, NOT from a browser param
 * @param {string} fullName
 * @returns {Promise<Array<{ runId: number, headSha: string, status: string, conclusion: string }>>}
 */
export async function listRiteRuns(userToken, repoId, fullName) {
  // Security: verify repo is in authorised list
  const authorised = await listAuthorizedRepos(userToken);
  if (!authorised.find(r => r.id === repoId))
    throw new Error(`Repo ${fullName} not in authorised installation list`);

  const resp = await fetch(
    `https://api.github.com/repos/${fullName}/actions/runs?per_page=20`,
    {
      headers: {
        Authorization: `Bearer ${userToken}`,
        Accept: 'application/vnd.github+json',
        'X-GitHub-Api-Version': '2022-11-28',
      },
    }
  );
  if (!resp.ok) throw new Error(`GitHub runs list failed: ${resp.status}`);
  const data = await resp.json();

  return (data.workflow_runs ?? []).map(run => ({
    runId: run.id,
    headSha: run.head_sha,
    status: run.status,
    conclusion: run.conclusion,
    createdAt: run.created_at,
    htmlUrl: run.html_url,
  }));
}

/**
 * Fetch and validate a Rite report artifact from a specific run.
 * Binds the report to the run's head SHA — rejects mismatches.
 * @param {string} installationToken — short-lived, from getInstallationToken
 * @param {string} fullName
 * @param {number} runId
 * @param {string} expectedSha — from GitHub run metadata
 * @returns {Promise<{ valid: boolean, report?: object, mismatch?: string }>}
 */
export async function fetchRunReport(installationToken, fullName, runId, expectedSha) {
  // 1. List artifacts for this run
  const artResp = await fetch(
    `https://api.github.com/repos/${fullName}/actions/runs/${runId}/artifacts`,
    {
      headers: {
        Authorization: `Bearer ${installationToken}`,
        Accept: 'application/vnd.github+json',
        'X-GitHub-Api-Version': '2022-11-28',
      },
    }
  );
