+  }
+  const artData = await artResp.json();
+  const artifact = artData.artifacts?.find(a => a.name === 'rite-report');
+  if (!artifact) {
+    return { valid: false, mismatch: 'No rite-report artifact found for this run.' };
+  }
+  if (artifact.expired) {
