// ------------------------------------------------------------------ //
// verify                                                               //
// ------------------------------------------------------------------ //

async function cmdVerify({ flags }) {
  const configArg = flags.config;
  if (!configArg) {
    stderr('Usage: rite verify --config <file> [--out <file>]');
    process.exit(3);
  }
  const configPath = resolve(configArg);
  if (!existsSync(configPath)) {
    stderr(`Config not found: ${configPath}`);
    process.exit(2);
  }

  // Parse config
  let config;
  try {
    config = JSON.parse(readFileSync(configPath, 'utf-8'));
  } catch (e) {
    stderr(`Failed to parse config: ${e.message}`);
    process.exit(2);
  }

  // Validate
  const errs = validateConfig(config);
  if (errs.length) {
    stderr('Config validation errors:');
    for (const e of errs) stderr(`  ${e}`);
    process.exit(2);
  }

  // Resolve adapter — must be inside the config's directory (no path traversal)
  const configDir = dirname(configPath);
  const adapterRel = config.adapter;
  const adapterPath = resolve(configDir, adapterRel);
  const relToConfig = relative(configDir, adapterPath);
  if (isAbsolute(relToConfig) || relToConfig.startsWith('..')) {
    stderr(`Adapter path escapes the config directory: ${adapterRel}`);
    process.exit(2);
  }
  if (!existsSync(adapterPath)) {
    stderr(`Adapter not found: ${adapterPath}`);
    process.exit(2);
  }

  // Load adapter
  let adapter;
  try {
    adapter = await import(pathToFileURL(adapterPath).href);
  } catch (e) {
    stderr(`Failed to load adapter: ${e.message}`);
    process.exit(2);
  }
  if (typeof adapter.runCase !== 'function') {
    stderr(`Adapter must export runCase() — not found in ${adapterPath}`);
    process.exit(2);
  }

  // Run
  let report;
  try {
    report = await verify(config, adapter, { configPath });
  } catch (e) {
    stderr(`Unexpected engine error: ${e.message}`);
    process.exit(2);
  }

  // Write JSON report
  const outArg = flags.out;
  if (outArg) {
    const outPath = resolve(outArg);
    writeFileSync(outPath, JSON.stringify(report, null, 2), 'utf-8');
    stderr(`Report written to: ${outPath}`);
  }

  // Write SARIF report
  const sarifArg = flags.sarif;
  if (sarifArg) {
    const sarifPath = resolve(sarifArg);
    const sarif = toSarif(report);
    writeFileSync(sarifPath, JSON.stringify(sarif, null, 2), 'utf-8');
    stderr(`SARIF written to: ${sarifPath}`);
  }

  renderReport(report);

  // Exit code by status
  if (report.status === 'PASS') process.exit(0);
  if (report.status === 'FAIL') process.exit(1);
  process.exit(2);
}

