102 |   /**
103 |    * Shared authorization and refund helper — the single guarded path to issueRefund.
104 |    * Validates request, reads canonical order, enforces all three policy conditions,
105 |    * then issues the refund. Both public entry points call this function.
106 |    *
107 |    * Validation order: request shape → actor context → order existence →
108 |    *   ownership → paid status → already-refunded → issue refund.
109 |    *
110 |    * @param {{ orderId: unknown }} request
111 |    * @param {{ actorId: unknown }|null|undefined} context
112 |    * @returns {{ ok: boolean, code: string, refundId?: string }}
113 |    */
114 |   function authorizeAndRefund(request, context) {
115 |     // 1. Request shape
116 |     if (
117 |       !request ||
118 |       typeof request !== 'object' ||
119 |       typeof (/** @type {Record<string,unknown>} */ (request).orderId) !== 'string' ||
120 |       /** @type {Record<string,unknown>} */ (request).orderId.trim() === ''
121 |     ) {
122 |       return { ok: false, code: 'INVALID_REQUEST' };
123 |     }
124 |     // Reject extra fields
125 |     const reqKeys = Object.keys(request);
126 |     for (const k of reqKeys) {
127 |       if (!ALLOWED_REQUEST_KEYS.has(k)) return { ok: false, code: 'INVALID_REQUEST' };
128 |     }
129 | 
130 |     // 2. Actor context
131 |     if (
132 |       !context ||
133 |       typeof context !== 'object' ||
134 |       typeof (/** @type {Record<string,unknown>} */ (context).actorId) !== 'string' ||
135 |       /** @type {Record<string,unknown>} */ (context).actorId.trim() === ''
136 |     ) {
137 |       return { ok: false, code: 'UNAUTHENTICATED' };
138 |     }
139 | 
140 |     const orderId = /** @type {string} */ (
141 |       /** @type {Record<string,unknown>} */ (request).orderId
142 |     );
143 |     const actorId = /** @type {string} */ (
144 |       /** @type {Record<string,unknown>} */ (context).actorId
145 |     );
146 | 
147 |     // 3. Order existence
148 |     const order = store.get(orderId);
149 |     if (!order) return { ok: false, code: 'NOT_FOUND' };
150 | 
151 |     // 4. Ownership — shared guard; applies to every caller path
152 |     if (order.ownerId !== actorId) return { ok: false, code: 'NOT_OWNER' };
153 | 
154 |     // 5. Paid status
155 |     if (order.paymentStatus !== 'paid') return { ok: false, code: 'NOT_PAID' };
156 | 
157 |     // 6. Already-refunded status
158 |     if (order.refunded) return { ok: false, code: 'ALREADY_REFUNDED' };
159 | 
160 |     // 7. Issue refund (single call site)
161 |     const { refundId } = issueRefund(order, actorId);
162 |     return { ok: true, code: 'REFUNDED', refundId };
163 |   }
164 | 
165 |   // ------------------------------------------------------------------ //
166 |   // Public API                                                            //
167 |   // ------------------------------------------------------------------ //
168 | 
169 |   /**
170 |    * Customer entry point.
171 |    * @param {object} request
172 |    * @param {object|null} context
173 |    */
174 |   function customerRefund(request, context) {
175 |     return authorizeAndRefund(request, context);
176 |   }
177 | 
178 |   /**
179 |    * Support entry point.
180 |    * Identical policy enforcement through the shared helper.
181 |    * "Support" identifies the caller path, not a permission to override ownership.
182 |    * @param {object} request
183 |    * @param {object|null} context
184 |    */
185 |   function supportRefund(request, context) {
186 |     return authorizeAndRefund(request, context);
187 |   }
188 | 
189 |   /**
190 |    * Return deep copies of current orders and events for observation.
191 |    * Callers cannot mutate the service through snapshot values.
192 |    * @returns {{ orders: object[], events: object[] }}
193 |    */
194 |   function snapshot() {
195 |     return {
196 |       orders: [...store.values()].map(cloneOrder),
197 |       events: events.map(e => ({ ...e })),
198 |     };
199 |   }
200 | 
201 |   return { customerRefund, supportRefund, snapshot };
202 | }
