8 |  * No DOM globals. No React. No Vite-specific globals.
9 |  * Filesystem reads (adapter import, config load) are handled by callers;
10 |  * this module receives already-parsed config and a resolved adapter path.
11 |  */
12 | 
13 | import { validateEffects } from '../instrument/effect-schema.js';
