22 | const VALID_DECISIONS = new Set(['allow', 'deny']);
23 | 
24 | /**
25 |  * @typedef {{
26 |  *   version: number,
27 |  *   ruleId: string,
28 |  *   rule: string,
29 |  *   adapter: string,
30 |  *   paths: Array<{ entry: string, sink: string, source: string }>,
31 |  *   cases: Array<{
32 |  *     id: string,
33 |  *     path: string,
34 |  *     actor: string,
35 |  *     input: object,
36 |  *     expected: {
37 |  *       decision: 'allow' | 'deny',
38 |  *       effects: object[],
39 |  *       stateChanged: boolean,
