45 | /**
46 |  * Validate a parsed config object.
47 |  * Returns an array of error strings (empty = valid).
48 |  * @param {unknown} config
49 |  * @returns {string[]}
50 |  */
51 | export function validateConfig(config) {
52 |   const errs = [];
53 |   if (!config || typeof config !== 'object') {
54 |     errs.push('config must be an object');
55 |     return errs;
56 |   }
57 |   const c = /** @type {Record<string,unknown>} */ (config);
58 | 
59 |   if (c.version !== 1) errs.push(`config.version must be 1 (got ${c.version})`);
60 |   if (typeof c.ruleId !== 'string' || !c.ruleId.trim())
61 |     errs.push('config.ruleId must be a non-empty string');
62 |   if (typeof c.rule !== 'string' || !c.rule.trim())
63 |     errs.push('config.rule must be a non-empty string');
64 |   if (typeof c.adapter !== 'string' || !c.adapter.trim())
65 |     errs.push('config.adapter must be a non-empty string');
66 | 
67 |   // Paths
68 |   if (!Array.isArray(c.paths) || c.paths.length === 0)
69 |     errs.push('config.paths must be a non-empty array');
70 |   else {
71 |     const pathNames = new Set();
72 |     for (let i = 0; i < c.paths.length; i++) {
73 |       const p = /** @type {Record<string,unknown>} */ (c.paths[i]);
74 |       if (typeof p.entry !== 'string' || !p.entry.trim())
75 |         errs.push(`config.paths[${i}].entry must be a non-empty string`);
76 |       else {
77 |         if (pathNames.has(p.entry)) errs.push(`Duplicate path entry: ${p.entry}`);
78 |         pathNames.add(p.entry);
79 |       }
80 |       if (typeof p.sink !== 'string' || !p.sink.trim())
81 |         errs.push(`config.paths[${i}].sink must be a non-empty string`);
82 |       if (typeof p.source !== 'string' || !p.source.trim())
83 |         errs.push(`config.paths[${i}].source must be a non-empty string`);
84 |     }
85 |   }
86 | 
87 |   // Cases
88 |   if (!Array.isArray(c.cases) || c.cases.length === 0)
89 |     errs.push('config.cases must be a non-empty array');
90 |   else {
91 |     const caseIds = new Set();
92 |     const configPaths = Array.isArray(c.paths)
93 |       ? new Set(c.paths.map(p => /** @type {Record<string,unknown>} */ (p).entry))
94 |       : new Set();
95 | 
96 |     for (let i = 0; i < c.cases.length; i++) {
97 |       const cs = /** @type {Record<string,unknown>} */ (c.cases[i]);
98 |       if (typeof cs.id !== 'string' || !cs.id.trim())
99 |         errs.push(`config.cases[${i}].id must be a non-empty string`);
100 |       else {
101 |         if (caseIds.has(cs.id)) errs.push(`Duplicate case id: ${cs.id}`);
102 |         caseIds.add(cs.id);
103 |       }
104 |       if (typeof cs.path !== 'string' || !cs.path.trim())
105 |         errs.push(`config.cases[${i}].path must be a non-empty string`);
106 |       else if (!configPaths.has(cs.path))
107 |         errs.push(`config.cases[${i}].path "${cs.path}" not in config.paths`);
108 |       if (typeof cs.actor !== 'string' || !cs.actor.trim())
109 |         errs.push(`config.cases[${i}].actor must be a non-empty string`);
110 |       if (!cs.input || typeof cs.input !== 'object')
111 |         errs.push(`config.cases[${i}].input must be an object`);
112 | 
113 |       const exp = /** @type {Record<string,unknown>} */ (cs.expected);
114 |       if (!exp || typeof exp !== 'object')
115 |         errs.push(`config.cases[${i}].expected must be an object`);
116 |       else {
117 |         if (!VALID_DECISIONS.has(/** @type {string} */ (exp.decision)))
118 |           errs.push(`config.cases[${i}].expected.decision must be 'allow'|'deny'`);
119 |         if (!Array.isArray(exp.effects))
120 |           errs.push(`config.cases[${i}].expected.effects must be an array`);
121 |         if (typeof exp.stateChanged !== 'boolean')
122 |           errs.push(`config.cases[${i}].expected.stateChanged must be a boolean`);
123 |       }
124 |     }
125 |   }
126 | 
127 |   return errs;
128 | }
