1 | /**
2 |  * src/instrument/effect-schema.js — Typed effect registry.
3 |  *
4 |  * Defines named sink event schemas. The engine validates adapter-reported
5 |  * effects against the registered schema before structural comparison.
6 |  * This prevents two adapters describing the same event differently from
7 |  * both passing silently.
8 |  *
9 |  * Schema format:
10 |  *   { field: 'type' | ['type', required?] }
11 |  * Types: 'string' | 'number' | 'boolean' | 'object' | 'any'
12 |  *
13 |  * Register your schema in rite.config.json under "effectSchema":
14 |  *   "effectSchema": "refund-event"
15 |  *
16 |  * Or inline in config:
17 |  *   "effectSchema": {
18 |  *     "orderId":    "string",
19 |  *     "actorId":    "string",
20 |  *     "amountCents": "number",
21 |  *     "currency":   "string"
22 |  *   }
23 |  */
24 | 
25 | // ------------------------------------------------------------------ //
26 | // Built-in schemas                                                     //
27 | // ------------------------------------------------------------------ //
28 | 
29 | /** @type {Record<string, Record<string, string | [string, boolean]>>} */
30 | const BUILT_IN_SCHEMAS = {
31 |   'refund-event': {
32 |     orderId:     'string',
33 |     actorId:     'string',
34 |     amountCents: 'number',
35 |     currency:    'string',
36 |   },
37 |   'transfer-event': {
38 |     fromAccountId: 'string',
39 |     toAccountId:   'string',
40 |     amountCents:   'number',
41 |     currency:      'string',
42 |   },
43 |   'permission-grant': {
44 |     subjectId:   'string',
45 |     resourceId:  'string',
46 |     permission:  'string',
47 |     grantedBy:   'string',
48 |   },
49 | };
50 | 
51 | // ------------------------------------------------------------------ //
52 | // Validator                                                            //
53 | // ------------------------------------------------------------------ //
54 | 
55 | /**
56 |  * Resolve a schema from either a registered name or an inline object.
57 |  * @param {string | Record<string,string> | undefined} schemaRef
58 |  * @returns {Record<string,string> | null}
59 |  */
60 | export function resolveSchema(schemaRef) {
61 |   if (!schemaRef) return null;
62 |   if (typeof schemaRef === 'string') return BUILT_IN_SCHEMAS[schemaRef] ?? null;
63 |   if (typeof schemaRef === 'object') return schemaRef;
64 |   return null;
65 | }
66 | 
67 | /**
68 |  * Validate one effect object against a schema.
69 |  * Returns an array of violation strings (empty = valid).
70 |  * @param {object} effect
71 |  * @param {Record<string,string>} schema
72 |  * @param {string} context — for error messages
73 |  * @returns {string[]}
74 |  */
75 | export function validateEffect(effect, schema, context = 'effect') {
76 |   const violations = [];
77 |   for (const [field, typeSpec] of Object.entries(schema)) {
78 |     const [expectedType, required = true] = Array.isArray(typeSpec) ? typeSpec : [typeSpec, true];
79 |     const value = /** @type {Record<string,unknown>} */ (effect)[field];
80 |     if (value === undefined || value === null) {
81 |       if (required) violations.push(`${context}.${field}: required field missing`);
82 |       continue;
83 |     }
84 |     if (expectedType === 'any') continue;
85 |     const actualType = typeof value;
86 |     if (actualType !== expectedType)
87 |       violations.push(`${context}.${field}: expected ${expectedType}; got ${actualType} (${JSON.stringify(value)})`);
88 |   }
89 |   // Reject unknown fields — adapters must not smuggle extra data
90 |   for (const key of Object.keys(effect)) {
91 |     if (!(key in schema))
92 |       violations.push(`${context}.${key}: unexpected field not in schema`);
93 |   }
94 |   return violations;
95 | }
96 | 
97 | /**
98 |  * Validate all effects in a case result against the config schema.
99 |  * Returns all violations across all effects.
100 |  * @param {object[]} effects
101 |  * @param {string | Record<string,string> | undefined} schemaRef
102 |  * @returns {string[]}
103 |  */
104 | export function validateEffects(effects, schemaRef) {
105 |   const schema = resolveSchema(schemaRef);
106 |   if (!schema || !Array.isArray(effects)) return [];
107 |   const violations = [];
108 |   for (let i = 0; i < effects.length; i++) {
109 |     violations.push(...validateEffect(effects[i], schema, `effects[${i}]`));
110 |   }
111 |   return violations;
112 | }
113 | 
114 | /** @returns {string[]} Names of all built-in schemas */
115 | export function listSchemas() {
116 |   return Object.keys(BUILT_IN_SCHEMAS);
117 | }
