1 | /**
2 |  * src/instrument/auto-adapter.js — Auto-adapter generator.
3 |  *
4 |  * Given a JS/TS module that exports named functions, wraps each target entry
5 |  * and sink with lightweight instrumentation — no code modification needed.
6 |  *
7 |  * How it works:
8 |  *   1. Dynamically imports the target module.
9 |  *   2. Wraps named entry functions to capture call arguments.
10 |  *   3. Wraps the named sink function to record every invocation.
11 |  *   4. Exposes runCase(caseSpec) using the same adapter contract as rite.adapter.mjs.
12 |  *
13 |  * Limitations:
14 |  *   - Works for ES modules and CJS modules with named exports.
15 |  *   - The sink must be exported OR accessible via a state object returned by a factory.
16 |  *   - Does not handle async generator patterns or prototype-chain dispatch.
17 |  *   - Does not instrument code behind dynamic require() or conditional imports.
18 |  *   - For complex services (dependency injection, class hierarchies), a manual
19 |  *     adapter is still recommended.
20 |  *
21 |  * Usage (programmatic):
22 |  *   import { generateAdapter } from './auto-adapter.js';
23 |  *   const adapter = await generateAdapter({
24 |  *     modulePath: './src/service.js',
25 |  *     factoryFn: 'createService',   // optional: if module exports a factory
26 |  *     factoryArgs: [{ orders: [...] }],
27 |  *     entries: ['customerRefund', 'supportRefund'],
28 |  *     sink: 'issueRefund',          // name to detect in call stack / exports
29 |  *     snapshotFn: 'snapshot',       // optional: for before/after state
30 |  *   });
31 |  *   const report = await verify(config, adapter);
32 |  *
33 |  * Usage (CLI):
34 |  *   rite instrument --module ./src/service.js \
35 |  *                   --factory createService \
36 |  *                   --entries customerRefund,supportRefund \
37 |  *                   --sink issueRefund \
38 |  *                   --snapshot snapshot \
39 |  *                   --out examples/generated/rite.adapter.mjs
40 |  */
