63 | /**
64 |  * Generate a live adapter object (not a file) by wrapping a loaded module.
65 |  * @param {InstrumentOptions} opts
66 |  * @returns {Promise<{ runCase: (caseSpec: object) => Promise<object> }>}
67 |  */
68 | export async function generateAdapter(opts) {
69 |   const { modulePath, factoryFn, factoryArgs = [], entries, sink, snapshotFn, seedBuilder } = opts;
70 | 
71 |   const mod = await import(pathToFileURL(modulePath).href);
72 | 
73 |   return {
74 |     /**
75 |      * runCase — conforms to the rite adapter contract.
76 |      */
77 |     async runCase(caseSpec) {
78 |       const { path: entryName, actor, input } = caseSpec;
79 | 
80 |       if (!entries.includes(entryName)) {
81 |         throw new Error(`Entry "${entryName}" not in instrumented entries: ${entries.join(', ')}`);
82 |       }
83 | 
84 |       // Build fixture args — use seedBuilder if provided, else empty
85 |       const seeds = seedBuilder ? seedBuilder(caseSpec) : [];
86 | 
87 |       // Create a fresh service instance per case
88 |       let instance;
89 |       const capturedSinkCalls = [];
90 | 
91 |       if (factoryFn) {
92 |         const factory = mod[factoryFn];
93 |         if (typeof factory !== 'function')
94 |           throw new Error(`Factory "${factoryFn}" not found in module`);
95 |         instance = factory(...(seeds.length ? [{ orders: seeds }, ...factoryArgs.slice(1)] : factoryArgs));
96 |       } else {
97 |         // Module-level exports: wrap directly
98 |         instance = mod;
