1 | /**
2 |  * src/graph/walker.js — Lightweight JS call-graph walker.
3 |  *
4 |  * Traces call paths from named entry functions to a named sink within
5 |  * a single JS/TS file using regex-based heuristics. Not a full AST parser —
6 |  * it reads function bodies and detects direct function calls by name.
7 |  *
8 |  * Limitations (stated explicitly):
9 |  *   - Single-file scope only; does not follow cross-file imports.
10 |  *   - Detects direct named calls: foo(), this.foo(), self.foo().
11 |  *   - Does not resolve aliases, computed calls, prototype chains, or closures
12 |  *     unless the called name literally appears in the source.
13 |  *   - Works well for module-pattern code (factory functions with closures).
14 |  *   - For large multi-file codebases, use a proper AST tool (acorn, ts-morph).
15 |  *
16 |  * Returns a PathTrace suitable for docs/path-map.md generation.
17 |  */
18 | 
19 | import { readFileSync } from 'node:fs';
20 | 
21 | // ------------------------------------------------------------------ //
22 | // Source reader                                                        //
23 | // ------------------------------------------------------------------ //
24 | 
25 | /**
26 |  * Extract named function/method bodies from JS source.
27 |  * Handles: function foo() {}, const foo = function() {}, const foo = () => {},
28 |  * foo(...) { ... } (method shorthand), async variants.
29 |  * @param {string} source
30 |  * @returns {Map<string, { body: string, startLine: number }>}
31 |  */
32 | function extractFunctions(source) {
33 |   const fns = new Map();
34 |   const lines = source.split('\n');
35 | 
36 |   // Pattern: function name(...) { OR const name = (...) => { OR async function name
37 |   const funcPattern = /(?:async\s+)?function\s+(\w+)\s*\(/g;
38 |   const arrowPattern = /(?:const|let|var)\s+(\w+)\s*=\s*(?:async\s+)?\(?[^)]*\)?\s*=>/g;
39 |   const methodPattern = /^\s*(?:async\s+)?(\w+)\s*\([^)]*\)\s*\{/gm;
40 | 
41 |   for (const [pattern, nameIdx] of [
42 |     [funcPattern, 1],
43 |     [arrowPattern, 1],
44 |     [methodPattern, 1],
45 |   ]) {
46 |     let match;
47 |     while ((match = pattern.exec(source)) !== null) {
48 |       const name = match[nameIdx];
49 |       if (!name || fns.has(name)) continue;
50 |       // Find the line number
51 |       const upTo = source.slice(0, match.index);
52 |       const startLine = upTo.split('\n').length;
53 |       // Extract body: find matching braces from match position
54 |       const bodyStart = source.indexOf('{', match.index);
55 |       if (bodyStart === -1) continue;
56 |       let depth = 0;
57 |       let bodyEnd = bodyStart;
58 |       for (let i = bodyStart; i < source.length; i++) {
59 |         if (source[i] === '{') depth++;
60 |         else if (source[i] === '}') {
61 |           depth--;
62 |           if (depth === 0) { bodyEnd = i; break; }
63 |         }
64 |       }
65 |       fns.set(name, { body: source.slice(bodyStart, bodyEnd + 1), startLine });
66 |     }
67 |   }
68 |   return fns;
69 | }
70 | 
71 | /**
72 |  * Find all function names called inside a function body.
73 |  * @param {string} body
74 |  * @returns {string[]}
75 |  */
76 | function findCalls(body) {
77 |   const calls = new Set();
78 |   // Match: word( OR this.word( OR self.word(
79 |   const callPattern = /(?:this\.|self\.)?(\w+)\s*\(/g;
80 |   let m;
81 |   while ((m = callPattern.exec(body)) !== null) {
82 |     const name = m[1];
83 |     // Filter out JS keywords and common built-ins
84 |     if (!['if', 'for', 'while', 'switch', 'catch', 'new', 'return', 'typeof',
85 |           'instanceof', 'await', 'async', 'function', 'class', 'import',
86 |           'console', 'Object', 'Array', 'String', 'Number', 'Promise',
87 |           'Error', 'Map', 'Set', 'JSON', 'Math'].includes(name)) {
88 |       calls.add(name);
89 |     }
90 |   }
91 |   return [...calls];
92 | }
93 | 
94 | // ------------------------------------------------------------------ //
95 | // Path trace                                                           //
96 | // ------------------------------------------------------------------ //
97 | 
98 | /**
99 |  * @typedef {{
100 |  *   entry: string,
101 |  *   sink: string,
102 |  *   path: string[],      // function call chain entry → … → sink
103 |  *   found: boolean,
104 |  *   startLine: number,
105 |  * }} PathTrace
106 |  */
107 | 
108 | /**
109 |  * BFS from entry toward sink, using extracted function bodies.
110 |  * @param {string} entry
111 |  * @param {string} sink
112 |  * @param {Map<string, { body: string, startLine: number }>} fns
113 |  * @returns {PathTrace}
114 |  */
115 | function tracePath(entry, sink, fns) {
116 |   const entryInfo = fns.get(entry);
117 |   if (!entryInfo) return { entry, sink, path: [entry], found: false, startLine: 0 };
118 | 
119 |   // BFS
120 |   const queue = [[entry]];
121 |   const visited = new Set([entry]);
122 | 
123 |   while (queue.length > 0) {
124 |     const currentPath = queue.shift();
125 |     const current = currentPath[currentPath.length - 1];
126 |     const fnInfo = fns.get(current);
127 |     if (!fnInfo) continue;
128 | 
129 |     const calls = findCalls(fnInfo.body);
130 |     for (const called of calls) {
131 |       if (called === sink) {
132 |         return {
133 |           entry,
134 |           sink,
135 |           path: [...currentPath, sink],
136 |           found: true,
137 |           startLine: entryInfo.startLine,
138 |         };
139 |       }
140 |       if (!visited.has(called) && fns.has(called)) {
141 |         visited.add(called);
142 |         queue.push([...currentPath, called]);
143 |       }
144 |     }
145 |   }
146 | 
147 |   return { entry, sink, path: [entry], found: false, startLine: entryInfo.startLine };
148 | }
149 | 
150 | // ------------------------------------------------------------------ //
151 | // Public API                                                           //
152 | // ------------------------------------------------------------------ //
153 | 
154 | /**
155 |  * @typedef {{
156 |  *   file: string,
157 |  *   entries: string[],
158 |  *   sink: string,
159 |  *   traces: PathTrace[],
160 |  *   functions: string[],
161 |  *   note: string,
162 |  * }} WalkResult
163 |  */
164 | 
165 | /**
166 |  * Walk a JS file and trace all named entry paths to a sink.
167 |  * @param {{ file: string, entries: string[], sink: string }} opts
168 |  * @returns {WalkResult}
169 |  */
170 | export function walkFile({ file, entries, sink }) {
171 |   const source = readFileSync(file, 'utf-8');
172 |   const fns = extractFunctions(source);
173 |   const traces = entries.map(entry => tracePath(entry, sink, fns));
174 |   return {
175 |     file,
176 |     entries,
177 |     sink,
178 |     traces,
179 |     functions: [...fns.keys()],
180 |     note: 'Regex-based single-file walker. Does not follow cross-file imports or resolve aliases.',
181 |   };
182 | }
183 | 
184 | /**
185 |  * Format a WalkResult as Markdown for docs/path-map.md.
186 |  * @param {WalkResult} result
187 |  * @returns {string}
188 |  */
189 | export function formatWalkResult(result) {
190 |   const lines = [];
191 |   lines.push(`## Auto-discovered paths in \`${result.file}\``);
192 |   lines.push('');
193 |   lines.push(`> ${result.note}`);
194 |   lines.push('');
195 | 
196 |   for (const trace of result.traces) {
197 |     const status = trace.found ? '✓ reaches sink' : '✗ no path to sink found';
198 |     lines.push(`### \`${trace.entry}\` → \`${trace.sink}\`  (${status})`);
199 |     if (trace.found) {
200 |       lines.push('');
201 |       lines.push('Call chain:');
202 |       lines.push('```');
203 |       lines.push(trace.path.join(' → '));
204 |       lines.push('```');
205 |     } else {
206 |       lines.push('');
207 |       lines.push('No direct call chain detected. The sink may be reached via a closure,');
208 |       lines.push('dynamic dispatch, or a cross-file import outside this walker\'s scope.');
209 |     }
210 |     lines.push('');
211 |   }
212 | 
213 |   lines.push('### All functions detected');
214 |   lines.push('');
215 |   for (const fn of result.functions) {
216 |     const reachesSink = result.traces.some(t => t.path.includes(fn) && t.found);
217 |     lines.push(`- \`${fn}\`${reachesSink ? '  ← on path to sink' : ''}`);
218 |   }
219 |   return lines.join('\n');
220 | }
