100 |  */
101 | async function fetchAndValidateReport(installationToken, fullName, runId, expectedSha) {
102 |   const headers = {
103 |     Authorization: `Bearer ${installationToken}`,
104 |     Accept: 'application/vnd.github+json',
105 |     'X-GitHub-Api-Version': '2022-11-28',
106 |     'User-Agent': 'rite-app/0.1.0',
107 |   };
108 | 
109 |   // 1. List artifacts
110 |   const artResp = await fetch(
111 |     `https://api.github.com/repos/${fullName}/actions/runs/${runId}/artifacts`,
112 |     { headers }
113 |   );
114 |   if (!artResp.ok) {
115 |     return { valid: false, mismatch: `GitHub artifact list failed: ${artResp.status} ${artResp.statusText}` };
116 |   }
117 |   const artData = await artResp.json();
118 |   const artifact = artData.artifacts?.find(a => a.name === 'rite-report');
119 |   if (!artifact) {
120 |     return { valid: false, mismatch: 'No rite-report artifact found for this run.' };
121 |   }
122 |   if (artifact.expired) {
123 |     return { valid: false, mismatch: 'Artifact has expired (GitHub 90-day retention limit).' };
124 |   }
125 | 
126 |   // 2. Download the artifact zip (GitHub redirects to a signed URL)
127 |   const dlResp = await fetch(artifact.archive_download_url, {
128 |     headers: { Authorization: `Bearer ${installationToken}`, 'User-Agent': 'rite-app/0.1.0' },
129 |     redirect: 'follow',
130 |   });
131 |   if (!dlResp.ok) {
132 |     return { valid: false, mismatch: `Artifact download failed: ${dlResp.status}` };
133 |   }
134 |   const zipBuffer = Buffer.from(await dlResp.arrayBuffer());
135 | 
136 |   // 3. Unzip and extract rite-report.json
137 |   let reportJson;
138 |   try {
139 |     const zip = new AdmZip(zipBuffer);
140 |     const entry = zip.getEntry('rite-report.json');
141 |     if (!entry) {
142 |       return { valid: false, mismatch: 'rite-report.json not found inside artifact zip.' };
143 |     }
144 |     reportJson = zip.readAsText(entry);
145 |   } catch (e) {
146 |     return { valid: false, mismatch: `Failed to read zip: ${e.message}` };
147 |   }
148 | 
149 |   // 4. Parse
150 |   let report;
151 |   try {
152 |     report = JSON.parse(reportJson);
153 |   } catch (e) {
154 |     return { valid: false, mismatch: `rite-report.json is not valid JSON: ${e.message}` };
155 |   }
156 | 
157 |   // 5. Schema validation
158 |   if (!report.schemaVersion || !report.status || !Array.isArray(report.results)) {
159 |     return { valid: false, mismatch: 'Report missing required fields (schemaVersion, status, results).' };
160 |   }
161 |   if (report.schemaVersion !== SCHEMA_VERSION) {
162 |     return { valid: false, mismatch: `Report schemaVersion ${report.schemaVersion} does not match engine ${SCHEMA_VERSION}.` };
163 |   }
164 | 
165 |   // 6. SHA binding — reject mismatch
166 |   if (report.commitSha && report.commitSha !== expectedSha) {
167 |     return {
168 |       valid: false,
169 |       mismatch: `Report commitSha (${report.commitSha}) does not match run headSha (${expectedSha}). Do not display.`,
170 |     };
171 |   }
172 | 
173 |   return { valid: true, report };
174 | }
