1 | /**
2 |  * src/mcp/server.js — Local MCP stdio server for Rite.
3 |  *
4 |  * Tools:
5 |  *   rite_analyze  — Read configured rule and path scope from a config file
6 |  *   rite_verify   — Run verification using the same core engine as the CLI
7 |  *   rite_report   — Read and render a saved report file
8 |  *
9 |  * Stdout carries MCP protocol messages only. Logs go to stderr.
10 |  * Workspace and file path arguments are validated; no generic shell execution.
11 |  *
12 |  * Start: node src/cli/rite.js mcp  (or rite mcp)
13 |  * Test:  npx @modelcontextprotocol/inspector node src/cli/rite.js mcp
14 |  */
15 | 
16 | import { readFileSync, writeFileSync, existsSync } from 'node:fs';
17 | import { resolve, dirname, relative, isAbsolute } from 'node:path';
18 | import { pathToFileURL } from 'node:url';
19 | import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
20 | import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
21 | import { z } from 'zod';
22 | import { validateConfig, verify, ENGINE_VERSION } from '../core/engine.js';
23 | 
24 | // ------------------------------------------------------------------ //
25 | // Helpers shared with CLI                                              //
26 | // ------------------------------------------------------------------ //
27 | 
28 | function safeJson(filePath) {
29 |   try {
30 |     return { ok: true, data: JSON.parse(readFileSync(filePath, 'utf-8')) };
31 |   } catch (e) {
32 |     return { ok: false, error: e.message };
33 |   }
34 | }
35 | 
36 | function renderReportText(report) {
37 |   const lines = [];
38 |   lines.push(`Rite v${ENGINE_VERSION} — ${report.ruleId}`);
39 |   lines.push(`Rule: ${report.rule}`);
40 |   lines.push(`Status: ${report.status}  Generated: ${report.generatedAt}`);
41 |   lines.push('');
42 |   for (const r of report.results) {
43 |     const icon = r.status === 'PASS' ? '✓' : r.status === 'FAIL' ? '✗' : '!';
44 |     lines.push(`${icon} ${r.status.padEnd(5)} [${r.path}] ${r.id}`);
45 |     if (r.failures?.length) {
46 |       for (const f of r.failures) lines.push(`    ${f}`);
47 |     }
48 |     if (r.error) lines.push(`    ERROR: ${r.error.split('\n')[0]}`);
49 |   }
50 |   const total  = report.results.length;
51 |   const passed = report.results.filter(r => r.status === 'PASS').length;
52 |   lines.push('');
53 |   lines.push(`${report.status}: ${passed}/${total} passed`);
54 |   return lines.join('\n');
55 | }
56 | 
57 | // ------------------------------------------------------------------ //
58 | // Server                                                               //
59 | // ------------------------------------------------------------------ //
60 | 
61 | export async function startMcpServer() {
62 |   const server = new McpServer({
63 |     name: 'rite',
64 |     version: ENGINE_VERSION,
65 |   });
66 | 
67 |   // ---- rite_analyze ------------------------------------------------ //
68 |   server.tool(
69 |     'rite_analyze',
70 |     'Read a Rite config file and return its rule, configured entry paths, and case summary.',
71 |     {
72 |       config: z.string().describe('Absolute or relative path to rite.config.json'),
73 |     },
74 |     async ({ config: configArg }) => {
75 |       const configPath = resolve(configArg);
76 |       if (!existsSync(configPath)) {
77 |         return { content: [{ type: 'text', text: `Config not found: ${configPath}` }], isError: true };
78 |       }
79 |       const parsed = safeJson(configPath);
80 |       if (!parsed.ok) {
81 |         return { content: [{ type: 'text', text: `Failed to parse config: ${parsed.error}` }], isError: true };
82 |       }
83 |       const errs = validateConfig(parsed.data);
84 |       if (errs.length) {
85 |         return { content: [{ type: 'text', text: `Config invalid:\n${errs.join('\n')}` }], isError: true };
86 |       }
87 |       const cfg = parsed.data;
88 |       const summary = [
89 |         `ruleId: ${cfg.ruleId}`,
90 |         `rule: ${cfg.rule}`,
91 |         '',
92 |         'Configured paths:',
93 |         ...cfg.paths.map(p => `  ${p.entry} → ${p.sink}  (${p.source})`),
94 |         '',
95 |         `Cases (${cfg.cases.length}):`,
96 |         ...cfg.cases.map(c => `  ${c.id}  [${c.path}]  actor=${c.actor}  expected=${c.expected.decision}`),
97 |       ].join('\n');
98 |       return { content: [{ type: 'text', text: summary }] };
99 |     }
100 |   );
101 | 
102 |   // ---- rite_verify ------------------------------------------------- //
103 |   server.tool(
104 |     'rite_verify',
105 |     'Run Rite verification using the same core engine as the CLI. Returns the full report as JSON.',
106 |     {
107 |       config: z.string().describe('Absolute or relative path to rite.config.json'),
108 |       out: z.string().optional().describe('Optional path to write the JSON report'),
109 |     },
110 |     async ({ config: configArg, out: outArg }) => {
111 |       const configPath = resolve(configArg);
112 |       if (!existsSync(configPath)) {
113 |         return { content: [{ type: 'text', text: `Config not found: ${configPath}` }], isError: true };
114 |       }
115 |       const parsed = safeJson(configPath);
116 |       if (!parsed.ok) {
117 |         return { content: [{ type: 'text', text: `Failed to parse config: ${parsed.error}` }], isError: true };
118 |       }
119 |       const errs = validateConfig(parsed.data);
120 |       if (errs.length) {
121 |         return { content: [{ type: 'text', text: `Config invalid:\n${errs.join('\n')}` }], isError: true };
122 |       }
123 | 
124 |       const cfg = parsed.data;
125 |       const configDir = dirname(configPath);
126 |       const adapterRel = cfg.adapter;
127 |       const adapterPath = resolve(configDir, adapterRel);
128 |       const relToConfig = relative(configDir, adapterPath);
129 |       if (isAbsolute(relToConfig) || relToConfig.startsWith('..')) {
130 |         return { content: [{ type: 'text', text: `Adapter path escapes config directory: ${adapterRel}` }], isError: true };
131 |       }
132 |       if (!existsSync(adapterPath)) {
133 |         return { content: [{ type: 'text', text: `Adapter not found: ${adapterPath}` }], isError: true };
134 |       }
135 | 
136 |       let adapter;
137 |       try {
138 |         adapter = await import(pathToFileURL(adapterPath).href);
139 |       } catch (e) {
140 |         return { content: [{ type: 'text', text: `Failed to load adapter: ${e.message}` }], isError: true };
141 |       }
142 |       if (typeof adapter.runCase !== 'function') {
143 |         return { content: [{ type: 'text', text: `Adapter does not export runCase()` }], isError: true };
144 |       }
145 | 
146 |       let report;
147 |       try {
148 |         report = await verify(cfg, adapter, { configPath });
149 |       } catch (e) {
150 |         return { content: [{ type: 'text', text: `Engine error: ${e.message}` }], isError: true };
151 |       }
152 | 
153 |       if (outArg) {
154 |         try {
155 |           writeFileSync(resolve(outArg), JSON.stringify(report, null, 2), 'utf-8');
156 |         } catch (e) {
157 |           process.stderr.write(`rite-mcp: could not write report: ${e.message}\n`);
158 |         }
159 |       }
160 | 
161 |       const text = renderReportText(report);
162 |       const json = JSON.stringify(report, null, 2);
163 |       return {
164 |         content: [
165 |           { type: 'text', text },
166 |           { type: 'text', text: '\n--- JSON ---\n' + json },
167 |         ],
168 |       };
169 |     }
170 |   );
171 | 
172 |   // ---- rite_report ------------------------------------------------- //
173 |   server.tool(
174 |     'rite_report',
175 |     'Read and render a saved Rite report JSON file.',
176 |     {
177 |       file: z.string().describe('Absolute or relative path to a Rite report JSON file'),
178 |     },
179 |     async ({ file }) => {
180 |       const filePath = resolve(file);
181 |       if (!existsSync(filePath)) {
182 |         return { content: [{ type: 'text', text: `Report not found: ${filePath}` }], isError: true };
183 |       }
184 |       const parsed = safeJson(filePath);
185 |       if (!parsed.ok) {
186 |         return { content: [{ type: 'text', text: `Failed to parse report: ${parsed.error}` }], isError: true };
187 |       }
188 |       const report = parsed.data;
189 |       if (!report.results || !report.status) {
190 |         return { content: [{ type: 'text', text: 'File does not look like a Rite report.' }], isError: true };
191 |       }
192 |       return { content: [{ type: 'text', text: renderReportText(report) }] };
193 |     }
194 |   );
195 | 
196 |   // Start transport
197 |   const transport = new StdioServerTransport();
198 |   await server.connect(transport);
199 |   process.stderr.write(`rite-mcp: server started (Rite v${ENGINE_VERSION})\n`);
200 | }
