1 | /**
2 |  * src/watsonx/draft.js — watsonx.ai case and path drafting.
3 |  *
4 |  * Sends a rule + limited code snippet to IBM watsonx.ai (via the chat API)
5 |  * and returns a candidate config diff for developer review.
6 |  *
7 |  * Authentication: IBM Cloud IAM API key → bearer token exchange.
8 |  * The token is never written to disk or logged.
9 |  *
10 |  * Environment variables (never passed to verify; server-side only):
11 |  *   IBMCLOUD_API_KEY     — IBM Cloud IAM API key
12 |  *   WATSONX_PROJECT_ID   — watsonx.ai project ID
13 |  *   WATSONX_REGION       — e.g. us-south (default)
14 |  *   WATSONX_MODEL_ID     — e.g. ibm/granite-3-3-8b-instruct (checked at runtime)
15 |  *
16 |  * If any credential is absent, draftCases() returns { available: false, reason }.
17 |  * The caller must display this state and never show a mocked response as live.
18 |  *
19 |  * API reference: https://cloud.ibm.com/docs/apis/watsonx-ai
20 |  */
21 | 
22 | const IAM_TOKEN_URL = 'https://iam.cloud.ibm.com/identity/token';
23 | const DEFAULT_REGION = 'us-south';
24 | 
25 | // ------------------------------------------------------------------ //
26 | // IAM token exchange                                                   //
27 | // ------------------------------------------------------------------ //
28 | 
29 | /**
30 |  * Exchange an IBM Cloud API key for a short-lived bearer token.
31 |  * @param {string} apiKey
32 |  * @returns {Promise<string>} access token
33 |  */
34 | async function getIamToken(apiKey) {
35 |   const body = new URLSearchParams({
36 |     grant_type: 'urn:ibm:params:oauth:grant-type:apikey',
37 |     apikey: apiKey,
38 |   });
39 | 
40 |   const resp = await fetch(IAM_TOKEN_URL, {
41 |     method: 'POST',
42 |     headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
43 |     body: body.toString(),
44 |   });
45 | 
46 |   if (!resp.ok) {
47 |     const text = await resp.text().catch(() => '');
48 |     throw new Error(`IAM token exchange failed (${resp.status}): ${text.slice(0, 200)}`);
49 |   }
50 | 
51 |   const data = await resp.json();
52 |   if (!data.access_token) throw new Error('IAM response missing access_token');
53 |   return data.access_token;
54 | }
55 | 
