60 | /**
61 |  * List available foundation models in the project.
62 |  * Returns the first Granite text model found, or null.
63 |  * @param {string} token
64 |  * @param {string} projectId
65 |  * @param {string} region
66 |  * @returns {Promise<string|null>}
67 |  */
68 | async function resolveModelId(token, projectId, region) {
69 |   const url = `https://${region}.ml.cloud.ibm.com/ml/v1/foundation_model_specs?version=2024-09-16&limit=50`;
70 |   try {
71 |     const resp = await fetch(url, {
72 |       headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
73 |     });
74 |     if (!resp.ok) return null;
75 |     const data = await resp.json();
76 |     const models = data.resources ?? [];
77 |     // Prefer a granite instruct model
78 |     const granite = models.find(m =>
79 |       m.model_id?.includes('granite') && m.model_id?.includes('instruct')
80 |     );
81 |     return granite?.model_id ?? models[0]?.model_id ?? null;
82 |   } catch {
83 |     return null;
84 |   }
85 | }
