1 | /**
2 |  * src/github/app.js — GitHub App server scaffold.
3 |  *
4 |  * Handles:
5 |  *   GET  /github/login          — Start OAuth flow
6 |  *   GET  /github/callback       — OAuth callback, set session
7 |  *   GET  /github/installations  — List repos the user authorised
8 |  *   GET  /github/runs           — List recent Rite workflow runs for a repo
9 |  *   GET  /github/report         — Fetch and validate a run's Rite report artifact
10 |  *   POST /github/logout         — Clear session
11 |  *
12 |  * Security model:
13 |  *   - User access token (user-to-server) for identity and session.
14 |  *   - Short-lived installation token (server-to-server) for artifact reads.
15 |  *   - App private key and session secret are environment variables — never
16 |  *     in browser assets, GitHub Actions logs, or Rite report JSON.
17 |  *   - Repository owner/name is NEVER trusted from a browser query parameter;
18 |  *     only repos in the user's authenticated installation list are served.
19 |  *   - Report schema and embedded SHA are validated against GitHub run metadata
20 |  *     before display. Mismatch → explicit error state, never PASS.
21 |  *
22 |  * Environment variables required:
23 |  *   GITHUB_APP_ID          — numeric App ID from GitHub App settings
24 |  *   GITHUB_APP_CLIENT_ID   — OAuth client ID
25 |  *   GITHUB_APP_CLIENT_SECRET
26 |  *   GITHUB_APP_PRIVATE_KEY — PEM key, newlines as \n
27 |  *   RITE_SESSION_SECRET    — Random 32+ char string for session signing
28 |  *   RITE_PUBLIC_URL        — e.g. https://rite.example.com (for OAuth callback)
29 |  *
30 |  * Status: SCAFFOLD — routes are defined and documented but the server is not
31 |  * started automatically. Register your GitHub App at github.com/settings/apps
32 |  * and set the environment variables above before enabling.
33 |  *
34 |  * GitHub App docs: https://docs.github.com/en/apps
35 |  */
36 | 
37 | // ------------------------------------------------------------------ //
38 | // Dependency check — these must be installed to use the GitHub server //
39 | // ------------------------------------------------------------------ //
40 | // npm install @octokit/app @octokit/oauth-app express express-session
41 | // They are NOT installed by default — kept out of the base bundle.
