44 | /**
45 |  * Check required environment variables.
46 |  * @returns {{ ok: boolean, missing: string[] }}
47 |  */
48 | export function checkEnv() {
49 |   const required = [
50 |     'GITHUB_APP_ID',
51 |     'GITHUB_APP_CLIENT_ID',
52 |     'GITHUB_APP_CLIENT_SECRET',
53 |     'GITHUB_APP_PRIVATE_KEY',
54 |     'RITE_SESSION_SECRET',
55 |     'RITE_PUBLIC_URL',
56 |   ];
57 |   const missing = required.filter(k => !process.env[k]);
58 |   return { ok: missing.length === 0, missing };
59 | }
