61 | /**
62 |  * Build the GitHub App OAuth authorization URL.
63 |  * @param {string} state — CSRF token, stored in session
64 |  * @returns {string}
65 |  */
66 | export function buildAuthUrl(state) {
67 |   const clientId = process.env.GITHUB_APP_CLIENT_ID ?? '';
68 |   const redirectUri = encodeURIComponent(`${process.env.RITE_PUBLIC_URL}/github/callback`);
69 |   return `https://github.com/login/oauth/authorize?client_id=${clientId}&redirect_uri=${redirectUri}&state=${state}&scope=read:user`;
70 | }
