72 | /**
73 |  * Exchange a GitHub OAuth code for a user access token.
74 |  * @param {string} code
75 |  * @returns {Promise<{ token: string, tokenType: string }>}
76 |  */
77 | export async function exchangeCode(code) {
78 |   const resp = await fetch('https://github.com/login/oauth/access_token', {
79 |     method: 'POST',
80 |     headers: { Accept: 'application/json', 'Content-Type': 'application/json' },
81 |     body: JSON.stringify({
82 |       client_id: process.env.GITHUB_APP_CLIENT_ID,
83 |       client_secret: process.env.GITHUB_APP_CLIENT_SECRET,
84 |       code,
85 |     }),
86 |   });
87 |   if (!resp.ok) throw new Error(`GitHub token exchange failed: ${resp.status}`);
88 |   const data = await resp.json();
89 |   if (data.error) throw new Error(`GitHub OAuth error: ${data.error_description ?? data.error}`);
90 |   return { token: data.access_token, tokenType: data.token_type };
