93 | /**
94 |  * List repositories accessible to the authenticated user via their installations.
95 |  * Uses the user access token — only repos the user authorised appear here.
96 |  * @param {string} userToken — user access token
97 |  * @returns {Promise<Array<{ id: number, fullName: string, installationId: number }>>}
98 |  */
99 | export async function listAuthorizedRepos(userToken) {
100 |   // 1. Get installations this user has authorised
101 |   const instResp = await fetch('https://api.github.com/user/installations', {
102 |     headers: {
103 |       Authorization: `Bearer ${userToken}`,
104 |       Accept: 'application/vnd.github+json',
105 |       'X-GitHub-Api-Version': '2022-11-28',
