134 | /**
135 |  * For baseline and mutation: a red phase is valid only when the wrong-owner
136 |  * case(s) fail through an observed unauthorized event, and all controls pass.
137 |  */
138 | function verifyBaselineExpectation(report, phaseId, expectedFailIds) {
139 |   const { ok: shapeOk, message: shapeMsg } = verifyReportShape(report, phaseId);
140 |   if (!shapeOk) return { expectationMet: false, message: shapeMsg, witnesses: [] };
141 | 
142 |   const sr = report.suiteReport;
143 |   const witnesses = [];
144 |   const unexpectedFails = [];
145 |   const missedFails = [];
146 | 
147 |   for (const r of sr.results) {
148 |     const shouldFail = expectedFailIds.includes(r.id);
149 |     if (shouldFail) {
150 |       if (r.status !== 'FAIL') {
151 |         missedFails.push(r.id);
152 |       } else {
153 |         // Verify there IS an unauthorized event in the failure (behavioral proof).
154 |         const unauthorized = r.failures.some(f =>
155 |           f.includes('new sink event') && f.includes('observed')
156 |         );
157 |         if (!unauthorized) {
158 |           return { expectationMet: false, message: `${r.id}: FAIL but no unauthorized-event witness`, witnesses: [] };
159 |         }
160 |         witnesses.push(r.id);
161 |       }
162 |     } else {
163 |       if (r.status !== 'PASS') unexpectedFails.push(r.id);
164 |     }
165 |   }
166 | 
167 |   if (missedFails.length > 0)
168 |     return { expectationMet: false, message: `Expected to fail: ${missedFails.join(', ')}`, witnesses };
169 |   if (unexpectedFails.length > 0)
170 |     return { expectationMet: false, message: `Unexpected failures: ${unexpectedFails.join(', ')}`, witnesses };
171 | 
172 |   return { expectationMet: true, message: 'behavioral failure detected as expected', witnesses };
173 | }
