1 | /**
2 |  * src/core/engine.js — Shared verification engine.
3 |  *
4 |  * verify(config, adapter, context) is the single function that owns
5 |  * validation, case execution, effect comparison, and report construction.
6 |  * CLI, MCP, and CI all call this function; none of them re-implement policy.
7 |  *
8 |  * No DOM globals. No React. No Vite-specific globals.
9 |  * Filesystem reads (adapter import, config load) are handled by callers;
10 |  * this module receives already-parsed config and a resolved adapter path.
11 |  */
12 | 
13 | import { validateEffects } from '../instrument/effect-schema.js';
14 | 
15 | export const SCHEMA_VERSION = 1;
16 | export const ENGINE_VERSION = '0.1.0';
17 | 
18 | // ------------------------------------------------------------------ //
19 | // Config validation                                                    //
20 | // ------------------------------------------------------------------ //
21 | 
22 | const VALID_DECISIONS = new Set(['allow', 'deny']);
23 | 
24 | /**
25 |  * @typedef {{
26 |  *   version: number,
27 |  *   ruleId: string,
28 |  *   rule: string,
29 |  *   adapter: string,
30 |  *   paths: Array<{ entry: string, sink: string, source: string }>,
31 |  *   cases: Array<{
32 |  *     id: string,
33 |  *     path: string,
34 |  *     actor: string,
35 |  *     input: object,
36 |  *     expected: {
37 |  *       decision: 'allow' | 'deny',
38 |  *       effects: object[],
39 |  *       stateChanged: boolean,
40 |  *     }
41 |  *   }>
42 |  * }} RiteConfig
43 |  */
44 | 
45 | /**
46 |  * Validate a parsed config object.
47 |  * Returns an array of error strings (empty = valid).
48 |  * @param {unknown} config
49 |  * @returns {string[]}
50 |  */
51 | export function validateConfig(config) {
52 |   const errs = [];
53 |   if (!config || typeof config !== 'object') {
54 |     errs.push('config must be an object');
55 |     return errs;
56 |   }
57 |   const c = /** @type {Record<string,unknown>} */ (config);
58 | 
59 |   if (c.version !== 1) errs.push(`config.version must be 1 (got ${c.version})`);
60 |   if (typeof c.ruleId !== 'string' || !c.ruleId.trim())
61 |     errs.push('config.ruleId must be a non-empty string');
62 |   if (typeof c.rule !== 'string' || !c.rule.trim())
63 |     errs.push('config.rule must be a non-empty string');
64 |   if (typeof c.adapter !== 'string' || !c.adapter.trim())
65 |     errs.push('config.adapter must be a non-empty string');
66 | 
67 |   // Paths
68 |   if (!Array.isArray(c.paths) || c.paths.length === 0)
69 |     errs.push('config.paths must be a non-empty array');
70 |   else {
71 |     const pathNames = new Set();
72 |     for (let i = 0; i < c.paths.length; i++) {
73 |       const p = /** @type {Record<string,unknown>} */ (c.paths[i]);
74 |       if (typeof p.entry !== 'string' || !p.entry.trim())
75 |         errs.push(`config.paths[${i}].entry must be a non-empty string`);
76 |       else {
77 |         if (pathNames.has(p.entry)) errs.push(`Duplicate path entry: ${p.entry}`);
78 |         pathNames.add(p.entry);
79 |       }
80 |       if (typeof p.sink !== 'string' || !p.sink.trim())
81 |         errs.push(`config.paths[${i}].sink must be a non-empty string`);
82 |       if (typeof p.source !== 'string' || !p.source.trim())
83 |         errs.push(`config.paths[${i}].source must be a non-empty string`);
84 |     }
85 |   }
86 | 
87 |   // Cases
88 |   if (!Array.isArray(c.cases) || c.cases.length === 0)
89 |     errs.push('config.cases must be a non-empty array');
90 |   else {
91 |     const caseIds = new Set();
92 |     const configPaths = Array.isArray(c.paths)
93 |       ? new Set(c.paths.map(p => /** @type {Record<string,unknown>} */ (p).entry))
94 |       : new Set();
95 | 
96 |     for (let i = 0; i < c.cases.length; i++) {
97 |       const cs = /** @type {Record<string,unknown>} */ (c.cases[i]);
98 |       if (typeof cs.id !== 'string' || !cs.id.trim())
99 |         errs.push(`config.cases[${i}].id must be a non-empty string`);
100 |       else {
101 |         if (caseIds.has(cs.id)) errs.push(`Duplicate case id: ${cs.id}`);
102 |         caseIds.add(cs.id);
103 |       }
104 |       if (typeof cs.path !== 'string' || !cs.path.trim())
105 |         errs.push(`config.cases[${i}].path must be a non-empty string`);
106 |       else if (!configPaths.has(cs.path))
107 |         errs.push(`config.cases[${i}].path "${cs.path}" not in config.paths`);
108 |       if (typeof cs.actor !== 'string' || !cs.actor.trim())
109 |         errs.push(`config.cases[${i}].actor must be a non-empty string`);
110 |       if (!cs.input || typeof cs.input !== 'object')
111 |         errs.push(`config.cases[${i}].input must be an object`);
112 | 
113 |       const exp = /** @type {Record<string,unknown>} */ (cs.expected);
114 |       if (!exp || typeof exp !== 'object')
115 |         errs.push(`config.cases[${i}].expected must be an object`);
116 |       else {
117 |         if (!VALID_DECISIONS.has(/** @type {string} */ (exp.decision)))
118 |           errs.push(`config.cases[${i}].expected.decision must be 'allow'|'deny'`);
119 |         if (!Array.isArray(exp.effects))
120 |           errs.push(`config.cases[${i}].expected.effects must be an array`);
121 |         if (typeof exp.stateChanged !== 'boolean')
122 |           errs.push(`config.cases[${i}].expected.stateChanged must be a boolean`);
123 |       }
124 |     }
125 |   }
126 | 
127 |   return errs;
128 | }
129 | 
130 | // ------------------------------------------------------------------ //
131 | // Case execution                                                       //
132 | // ------------------------------------------------------------------ //
133 | 
134 | /**
135 |  * @typedef {{
136 |  *   id: string,
137 |  *   path: string,
138 |  *   status: 'PASS'|'FAIL'|'ERROR',
139 |  *   expected: object,
140 |  *   observed: object,
141 |  *   failures: string[],
142 |  *   error: string | null,
143 |  * }} CaseResult
144 |  */
145 | 
146 | /**
147 |  * Run one case through the adapter.
148 |  * The adapter is responsible for all isolation and fixture setup.
149 |  * @param {object} caseSpec
150 |  * @param {object} adapter  — { runCase }
151 |  * @returns {Promise<CaseResult>}
152 |  */
153 | async function runOneCase(caseSpec, adapter) {
154 |   const result = {
155 |     id: caseSpec.id,
156 |     path: caseSpec.path,
157 |     status: /** @type {'PASS'|'FAIL'|'ERROR'} */ ('PASS'),
158 |     expected: caseSpec.expected,
159 |     observed: null,
160 |     failures: [],
161 |     error: null,
162 |   };
163 | 
164 |   let observed;
165 |   try {
166 |     observed = await adapter.runCase(caseSpec);
167 |   } catch (err) {
168 |     result.status = 'ERROR';
169 |     result.error = err instanceof Error ? `${err.message}\n${err.stack}` : String(err);
170 |     return result;
171 |   }
172 | 
173 |   if (!observed || typeof observed !== 'object') {
174 |     result.status = 'ERROR';
175 |     result.error = `Adapter returned non-object: ${JSON.stringify(observed)}`;
176 |     return result;
177 |   }
178 | 
179 |   result.observed = observed;
180 | 
181 |   const exp = caseSpec.expected;
182 |   const failures = [];
183 | 
184 |   // 1. Decision
185 |   const observedDecision = observed.decision;
186 |   if (observedDecision !== exp.decision)
187 |     failures.push(`decision: expected "${exp.decision}"; observed "${observedDecision}"`);
188 | 
189 |   // 2. Effect count — a denial that produces effects is FAIL regardless of decision match
190 |   const observedEffects = Array.isArray(observed.effects) ? observed.effects : [];
191 |   if (observedEffects.length !== exp.effects.length)
192 |     failures.push(
193 |       `effects count: expected ${exp.effects.length}; observed ${observedEffects.length}` +
194 |       (observedEffects.length > 0 ? ` (first: ${JSON.stringify(observedEffects[0])})` : '')
195 |     );
196 | 
197 |   // 3. Effect content — compare each expected effect structurally
198 |   for (let i = 0; i < exp.effects.length; i++) {
199 |     const eEff = exp.effects[i];
200 |     const oEff = observedEffects[i];
201 |     if (!oEff) break; // already caught by count check
202 |     for (const key of Object.keys(eEff)) {
203 |       if (eEff[key] !== oEff[key])
204 |         failures.push(`effects[${i}].${key}: expected ${JSON.stringify(eEff[key])}; observed ${JSON.stringify(oEff[key])}`);
205 |     }
206 |   }
207 | 
208 |   // 4. Effect schema validation (if config provides effectSchema)
209 |   if (caseSpec.effectSchema && observedEffects.length > 0) {
210 |     const schemaViolations = validateEffects(observedEffects, caseSpec.effectSchema);
211 |     for (const v of schemaViolations)
212 |       failures.push(`schema: ${v}`);
213 |   }
214 | 
215 |   // 5. State change
216 |   const observedStateChanged = observed.stateChanged;
217 |   if (observedStateChanged !== exp.stateChanged)
218 |     failures.push(`stateChanged: expected ${exp.stateChanged}; observed ${observedStateChanged}`);
219 | 
220 |   result.failures = failures;
221 |   result.status = failures.length > 0 ? 'FAIL' : 'PASS';
222 |   return result;
223 | }
224 | 
225 | // ------------------------------------------------------------------ //
226 | // Main verify function                                                 //
227 | // ------------------------------------------------------------------ //
228 | 
229 | /**
230 |  * @typedef {{
231 |  *   schemaVersion: number,
232 |  *   engineVersion: string,
233 |  *   ruleId: string,
234 |  *   rule: string,
235 |  *   configuredPaths: Array<{ entry: string, sink: string, source: string }>,
236 |  *   generatedAt: string,
237 |  *   status: 'PASS'|'FAIL'|'ERROR',
238 |  *   results: CaseResult[],
239 |  *   error: string | null,
240 |  * }} VerifyReport
241 |  */
242 | 
243 | /**
244 |  * Run the full verification against a loaded adapter.
245 |  * Returns a VerifyReport regardless of pass/fail.
246 |  *
247 |  * @param {RiteConfig} config
248 |  * @param {{ runCase: (caseSpec: object) => Promise<object> }} adapter
249 |  * @param {{ configPath?: string }} [context]
250 |  * @returns {Promise<VerifyReport>}
251 |  */
252 | export async function verify(config, adapter, context = {}) {
253 |   const report = {
254 |     schemaVersion: SCHEMA_VERSION,
255 |     engineVersion: ENGINE_VERSION,
256 |     ruleId: config.ruleId,
257 |     rule: config.rule,
258 |     configuredPaths: config.paths,
259 |     generatedAt: new Date().toISOString(),
260 |     status: /** @type {'PASS'|'FAIL'|'ERROR'} */ ('PASS'),
261 |     results: [],
262 |     error: null,
263 |   };
264 | 
265 |   if (!config.cases?.length) {
266 |     report.status = 'ERROR';
267 |     report.error = 'No cases configured.';
268 |     return report;
269 |   }
270 | 
271 |   for (const caseSpec of config.cases) {
272 |     const result = await runOneCase(caseSpec, adapter);
273 |     report.results.push(result);
274 |   }
275 | 
276 |   // Aggregate: ERROR > FAIL > PASS
277 |   let status = 'PASS';
278 |   for (const r of report.results) {
279 |     if (r.status === 'ERROR') { status = 'ERROR'; break; }
280 |     if (r.status === 'FAIL') status = 'FAIL';
281 |   }
282 |   report.status = /** @type {'PASS'|'FAIL'|'ERROR'} */ (status);
283 | 
284 |   return report;
285 | }
