  const { ok: shapeOk, message: shapeMsg } = verifyReportShape(report, phaseId);
  if (!shapeOk) return { expectationMet: false, message: shapeMsg, witnesses: [] };
  const sr = report.suiteReport;
  if (sr.status !== 'PASS')
