  ruleId: 'my-rule',
  rule: 'Describe the authorization rule here.',
  adapter: './rite.adapter.mjs',
  paths: [
    { entry: 'myEntry', sink: 'mySink', source: 'src/service.js' },
  ],
  cases: [
    {
      id: 'allow-example',
      path: 'myEntry',
      actor: 'actor-id',
      input: { resourceId: 'resource-1' },
      expected: { decision: 'allow', effects: [], stateChanged: false },
    },
    {
      id: 'deny-example',
      path: 'myEntry',
      actor: 'other-actor',
      input: { resourceId: 'resource-1' },
