  rite report <file>
  rite graph --file <js-file> --entries fn1,fn2 --sink sinkFn
  rite instrument --module <file> --entries fn1,fn2 --sink sinkFn [--factory fn] [--snapshot fn] [--out adapter.mjs]
  rite draft --rule <file> [--snippet <file>]
